25	const (
26		historyDirName           = "history"
27		historyIndexFileName     = "index.json"
28		historyIndexPath         = historyDirName + "/" + historyIndexFileName
29		historyScanCacheFileName = "scan-cache.json.gz"
30		historyScanCachePath     = historyDirName + "/" + historyScanCacheFileName
31		historyMaxLineBytes      = 1024 * 1024
32		// historyScanCacheVersion gates reuse of cached per-file scan results.
33		// Bump it whenever the history record extraction/classification logic
34		// changes so stale cached records are discarded on the next refresh.
35		// v2: index user prompts as "request" records.
36		// v3: stop EXTRACTING request records during scan (the v2 indexing) — they were
37		// excluded from general ranking (measured noise) and the only surfaces that
38		// could query them (inspect requests / brain_history kind=requests) were
39		// removed. The request-kind gates/filtering are kept as defensive support for
40		// stale indexes; bumping discards per-file scan caches that still hold request
41		// records so they stop reappearing on refresh.
42		// v4: RE-introduce request extraction (wrapper-filtered, via
43		// transcriptUserText). Two Phase 2 consumers reopened the v3 closed
44		// question with new evidence: `brief --handoff` needs each session's
45		// opening request and the history eval's midtask stratum mines follow-up
46		// questions as queries. The v3 noise concern is unchanged and unaffected:
47		// both rankers still exclude kind=request from general ranking.
48		historyScanCacheVersion = 4
49	)
