98	// historyScanCache memoizes the parsed history records for each session
99	// transcript so a refresh only re-scans files whose size or mtime changed.
100	// Session transcripts are content-stable across refreshes (the export step
101	// reuses unchanged transcripts via the export cursor), so the (size, mtime)
102	// pair is a reliable change signal and lets the index skip both the I/O and
103	// the parse for the vast majority of files on every run.
104	type historyScanCache struct {
105		Version int                              `json:"version"`
106		Files   map[string]historyScanCacheEntry `json:"files"`
107	}
108	
109	type historyScanCacheEntry struct {
110		Size        int64           `json:"size"`
111		ModUnixNano int64           `json:"mod_unix_nano"`
112		Records     []historyRecord `json:"records"`
113	}
