115	func newHistoryIndexCommand(opts Options) *cobra.Command {
116		cmd := &cobra.Command{
117			Use:   "history [path]",
118			Short: "Rebuild the decision/rationale history index from exported session transcripts",
119			Args:  cobra.MaximumNArgs(1),
120			RunE: func(cmd *cobra.Command, args []string) error {
121				target := "."
122				if opts.Env.RepoRoot != "" {
123					target = opts.Env.RepoRoot
124				}
125				if len(args) == 1 {
126					target = args[0]
127				}
128				return runHistoryIndex(cmd.Context(), cmd, opts, target)
129			},
130		}
131		return cmd
132	}
133	
134	func runHistoryIndex(ctx context.Context, cmd *cobra.Command, opts Options, target string) error {
135		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
136		if err != nil {
137			return err
138		}
139		if !local {
140			return fmt.Errorf("refresh history requires a local repository path: %s", target)
141		}
142		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
143		if err != nil {
144			return err
145		}
146		source, err := writeBrainHistoryIndexAndSource(storage.BrainDir, opts.Now().UTC(), nil)
147		if err != nil {
148			return err
149		}
150		fmt.Fprintf(cmd.OutOrStdout(), "indexed %d history records: %s\n", source.Records, filepath.Join(storage.BrainDir, filepath.FromSlash(source.IndexPath)))
151		// History vectors ride the history stage (standalone here, and the same
152		// sequence inside the full `refresh`): only under the ENTIRE_BRAIN_EMBEDDER
153		// opt-in, see history_vec.go for the gate and sizing rationale.
154		if strings.TrimSpace(os.Getenv("ENTIRE_BRAIN_EMBEDDER")) != "" {
155			e := historySemanticEmbedder(defaultEmbedder())
156			store, storeOK := historyVectorStoreFor(storage.BrainDir, e)
157			switch {
158			case e == nil:
159				fmt.Fprintln(cmd.OutOrStdout(), "history vectors: skipped (embed server unavailable)")
160			case !storeOK:
161				fmt.Fprintln(cmd.OutOrStdout(), "history vectors: skipped (requires the brain_cgo build)")
162			default:
163				index, ierr := loadBrainHistoryIndex(storage.BrainDir, source)
164				if ierr != nil {
165					return ierr
166				}
167				// Flush-batch progress to stderr: the first sync of a large repo
168				// embeds every record and can run for hours — silence would read
169				// as a hang.
170				added, dropped, total, serr := syncHistoryVectors(store, index, e, func(done, totalNew int) {
171					fmt.Fprintf(cmd.ErrOrStderr(), "history vectors: %d/%d new %s embedded\n", done, totalNew, pluralUnit("record", totalNew))
172				})
173				if serr != nil {
174					return serr
175				}
176				fmt.Fprintf(cmd.OutOrStdout(), "history vectors: %d embedded, %d pruned (%d total)\n", added, dropped, total)
177			}
178		}
179		return nil
180	}
