182	// historyIndexProgress reports incremental progress while the history index is
183	// rebuilt. done counts session files processed so far out of total. It is
184	// optional; pass nil when no progress reporting is needed.
185	type historyIndexProgress func(done, total int)
186	
187	func writeBrainHistoryIndexAndSource(outputDir string, now time.Time, progress historyIndexProgress) (*historySourceManifest, error) {
188		var source *historySourceManifest
189		err := withBrainWriteLock(outputDir, func() error {
190			var runErr error
191			source, runErr = writeBrainHistoryIndexAndSourceLocked(outputDir, now, progress)
192			return runErr
193		})
194		return source, err
195	}
196	
197	func writeBrainHistoryIndexAndSourceLocked(outputDir string, now time.Time, progress historyIndexProgress) (*historySourceManifest, error) {
198		index, source, err := buildBrainHistoryIndex(outputDir, now, progress)
199		if err != nil {
200			return nil, err
201		}
202		data, err := json.MarshalIndent(index, "", "  ")
203		if err != nil {
204			return nil, err
205		}
206		data = append(data, '\n')
207		if err := writeBrainRelativeFileAtomic(outputDir, historyIndexPath, data, 0o600); err != nil {
208			return nil, fmt.Errorf("write history index: %w", err)
209		}
210		// Build the derived BM25 index alongside its truth so the search/query verbs
211		// do not pay a first-query rebuild. Best-effort: the query path rebuilds it
212		// lazily on any failure, so this must never fail the refresh.
213		if db, ftsErr := openHistoryFTSLocked(outputDir, index); ftsErr == nil {
214			_ = db.Close()
215		}
216		manifest, err := loadBrainManifest(outputDir)
217		if err != nil {
218			return nil, err
219		}
220		if manifest.Sources == nil {
221			manifest.Sources = &brainSources{}
222		}
223		manifest.Sources.History = source
224		if manifest.GeneratedAt.IsZero() {
225			manifest.GeneratedAt = now
226		}
227		if err := writeBrainManifestAndReadme(outputDir, *manifest); err != nil {
228			return nil, err
229		}
230		return source, nil
231	}
