233	func buildBrainHistoryIndex(outputDir string, now time.Time, progress historyIndexProgress) (historyIndex, *historySourceManifest, error) {
234		sessionsRoot := filepath.Join(outputDir, exportSessionsDirectory)
235		index := historyIndex{GeneratedAt: now}
236		if _, err := os.Stat(sessionsRoot); err != nil {
237			if os.IsNotExist(err) {
238				return index, nil, errors.New("session history missing; run `entire brain refresh sessions` first")
239			}
240			return index, nil, err
241		}
242		files, err := collectHistorySessionFiles(sessionsRoot, &index.Warnings)
243		if err != nil {
244			return index, nil, err
245		}
246	
247		prevCache := loadHistoryScanCache(outputDir)
248		newCache := historyScanCache{Version: historyScanCacheVersion, Files: make(map[string]historyScanCacheEntry, len(files))}
249		manifest, _ := loadBrainManifest(outputDir)
250		branchByPath := historyBranchByTranscriptPath(manifest)
251	
252		total := len(files)
253		if progress != nil {
254			progress(0, total)
255		}
256		seenDecisions := map[string]struct{}{}
257		for i, file := range files {
258			rel, relErr := filepath.Rel(outputDir, file.Path)
259			if relErr != nil {
260				rel = file.Path
261			}
262			rel = filepath.ToSlash(rel)
263	
264			var records []historyRecord
265			if cached, ok := prevCache.Files[rel]; ok && cached.Size == file.Size && cached.ModUnixNano == file.ModUnixNano {
266				records = cached.Records
267			} else {
268				scanned, scanErr := scanHistoryFile(outputDir, file.Path)
269				if scanErr != nil {
270					index.Warnings = append(index.Warnings, scanErr.Error())
271					if progress != nil {
272						progress(i+1, total)
273					}
274					continue
275				}
276				records = scanned
277			}
278			records = annotateHistoryRecordBranches(records, rel, branchByPath)
279			// Only files that scanned cleanly (or were reused) are cached; a file
280			// that errored is left out so the next refresh retries it.
281			newCache.Files[rel] = historyScanCacheEntry{Size: file.Size, ModUnixNano: file.ModUnixNano, Records: records}
282	
283			for _, record := range records {
284				if record.Kind == "decision" {
285					dedupeKey := normalizeHistorySearchText(record.Summary)
286					if _, ok := seenDecisions[dedupeKey]; ok {
287						continue
288					}
289					seenDecisions[dedupeKey] = struct{}{}
290				}
291				index.Records = append(index.Records, record)
292			}
293			if progress != nil {
294				progress(i+1, total)
295			}
296		}
297		saveHistoryScanCache(outputDir, newCache)
298		sort.Slice(index.Records, func(i, j int) bool {
299			if index.Records[i].Kind != index.Records[j].Kind {
300				return index.Records[i].Kind < index.Records[j].Kind
301			}
302			if index.Records[i].Path != index.Records[j].Path {
303				return index.Records[i].Path < index.Records[j].Path
304			}
305			return index.Records[i].Line < index.Records[j].Line
306		})
307		source := &historySourceManifest{
308			GeneratedAt:         now,
309			IndexPath:           historyIndexPath,
310			SessionsFingerprint: brainSessionsFingerprint(outputDir),
311			Records:             len(index.Records),
312			Warnings:            append([]string(nil), index.Warnings...),
313		}
314		for _, record := range index.Records {
315			switch record.Kind {
316			case "decision":
317				source.Decisions++
318			case "learning":
319				source.Learnings++
320			case "validation":
321				source.Validations++
322			case "tool_call":
323				source.ToolCalls++
324			case "code_fact":
325				source.CodeFacts++
326			}
327		}
328		return index, source, nil
329	}
