331	func historyBranchByTranscriptPath(manifest *exportManifest) map[string]string {
332		out := map[string]string{}
333		if manifest == nil || manifest.Sources == nil || manifest.Sources.Sessions == nil {
334			return out
335		}
336		defaultBranch := strings.TrimSpace(manifest.Sources.Sessions.DefaultBranch)
337		if defaultBranch == "" {
338			defaultBranch = strings.TrimSpace(manifest.DefaultBranch)
339		}
340		if defaultBranch == "" {
341			defaultBranch = distillDefaultBranch
342		}
343		for _, session := range manifest.Sources.Sessions.Sessions {
344			rel := filepath.ToSlash(strings.TrimSpace(session.TranscriptPath))
345			if rel == "" {
346				continue
347			}
348			branch := strings.TrimSpace(session.Branch)
349			if branch == "" {
350				branch = defaultBranch
351			}
352			out[rel] = branch
353		}
354		return out
355	}
356	
357	func annotateHistoryRecordBranches(records []historyRecord, rel string, branchByPath map[string]string) []historyRecord {
358		branch := historyRecordBranchForPath(rel, branchByPath)
359		if branch == "" {
360			return records
361		}
362		out := append([]historyRecord(nil), records...)
363		for i := range out {
364			if out[i].Branch == "" {
365				out[i].Branch = branch
366			}
367		}
368		return out
369	}
370	
371	func historyRecordBranchForPath(path string, branchByPath map[string]string) string {
372		rel := filepath.ToSlash(strings.TrimSpace(path))
373		if rel == "" {
374			return ""
375		}
376		if branch := strings.TrimSpace(branchByPath[rel]); branch != "" {
377			return branch
378		}
379		if strings.HasPrefix(rel, "sessions/branches/") {
380			rest := strings.TrimPrefix(rel, "sessions/branches/")
381			if idx := strings.Index(rest, "/"); idx > 0 {
382				return rest[:idx]
383			}
384		}
385		if strings.HasPrefix(rel, "sessions/") {
386			rest := strings.TrimPrefix(rel, "sessions/")
387			if idx := strings.Index(rest, "/"); idx > 0 {
388				return rest[:idx]
389			}
390		}
391		return ""
392	}
