394	// loadHistoryScanCache reads the per-file scan cache. It always returns a
395	// usable (non-nil map) value: any read/parse error or a version mismatch
396	// yields an empty cache so the index simply rebuilds from scratch.
397	// The cache stores every indexed record for every session, which at scale is
398	// hundreds of megabytes of JSON. It is gzip-compressed on disk to bound the
399	// footprint (the record text compresses heavily).
400	func loadHistoryScanCache(outputDir string) historyScanCache {
401		empty := historyScanCache{Version: historyScanCacheVersion, Files: map[string]historyScanCacheEntry{}}
402		data, err := os.ReadFile(filepath.Join(outputDir, filepath.FromSlash(historyScanCachePath)))
403		if err != nil {
404			return empty
405		}
406		gz, err := gzip.NewReader(bytes.NewReader(data))
407		if err != nil {
408			return empty
409		}
410		defer gz.Close()
411		// Bound the decompressed stream so a gzip bomb cannot exhaust memory; an
412		// over-cap or truncated stream simply rebuilds the cache from scratch.
413		limited := io.LimitReader(gz, semanticSnapshotMaxBytes())
414		var cache historyScanCache
415		if err := json.NewDecoder(limited).Decode(&cache); err != nil {
416			return empty
417		}
418		if cache.Version != historyScanCacheVersion || cache.Files == nil {
419			return empty
420		}
421		return cache
422	}
423	
424	// saveHistoryScanCache persists the per-file scan cache. Failures are
425	// non-fatal: a missing or unwritable cache only costs a full rebuild next time.
426	func saveHistoryScanCache(outputDir string, cache historyScanCache) {
427		var buf bytes.Buffer
428		gz := gzip.NewWriter(&buf)
429		if err := json.NewEncoder(gz).Encode(cache); err != nil {
430			return
431		}
432		if err := gz.Close(); err != nil {
433			return
434		}
435		_ = writeBrainRelativeFileAtomic(outputDir, historyScanCachePath, buf.Bytes(), 0o600)
436	}
