438	func brainSessionsFingerprint(outputDir string) string {
439		manifest, err := loadBrainManifest(outputDir)
440		if err != nil || manifest.Sources == nil || manifest.Sources.Sessions == nil {
441			return ""
442		}
443		return sessionSourceFingerprint(manifest.Sources.Sessions)
444	}
