446	func sessionSourceFingerprint(source *sessionSourceManifest) string {
447		if source == nil {
448			return ""
449		}
450		type fingerprintSession struct {
451			SessionID        string `json:"session_id"`
452			LatestCheckpoint string `json:"latest_checkpoint_id"`
453			Branch           string `json:"branch,omitempty"`
454			TranscriptPath   string `json:"transcript_path"`
455		}
456		payload := struct {
457			DefaultBranch      string               `json:"default_branch,omitempty"`
458			TranscriptMode     string               `json:"transcript_mode"`
459			Scope              string               `json:"scope"`
460			LatestCheckpointID string               `json:"latest_checkpoint_id,omitempty"`
461			Sessions           []fingerprintSession `json:"sessions"`
462		}{
463			DefaultBranch:      source.DefaultBranch,
464			TranscriptMode:     source.TranscriptMode,
465			Scope:              source.Scope,
466			LatestCheckpointID: source.LatestCheckpointID,
467			Sessions:           make([]fingerprintSession, 0, len(source.Sessions)),
468		}
469		for _, session := range source.Sessions {
470			payload.Sessions = append(payload.Sessions, fingerprintSession{
471				SessionID:        session.SessionID,
472				LatestCheckpoint: session.LatestCheckpoint,
473				Branch:           session.Branch,
474				TranscriptPath:   session.TranscriptPath,
475			})
476		}
477		data, err := json.Marshal(payload)
478		if err != nil {
479			return ""
480		}
481		sum := sha256.Sum256(data)
482		return "sha256:" + hex.EncodeToString(sum[:])
483	}
484	
485	func collectHistorySessionFiles(sessionsRoot string, warnings *[]string) ([]historySessionFile, error) {
486		var files []historySessionFile
487		err := filepath.WalkDir(sessionsRoot, func(path string, d fs.DirEntry, err error) error {
488			if err != nil {
489				*warnings = append(*warnings, err.Error())
490				return nil
491			}
492			if d.IsDir() {
493				return nil
494			}
495			ext := filepath.Ext(path)
496			if ext != ".jsonl" && ext != ".json" && ext != ".md" && ext != ".txt" {
497				return nil
498			}
499			info, statErr := d.Info()
500			if statErr != nil {
501				*warnings = append(*warnings, statErr.Error())
502				return nil
503			}
504			files = append(files, historySessionFile{
505				Path:        path,
506				SortTime:    historySessionSortTime(path, info.ModTime()),
507				Size:        info.Size(),
508				ModUnixNano: info.ModTime().UnixNano(),
509			})
510			return nil
511		})
512		if err != nil {
513			return nil, err
514		}
515		sort.Slice(files, func(i, j int) bool {
516			if !files[i].SortTime.Equal(files[j].SortTime) {
517				return files[i].SortTime.After(files[j].SortTime)
518			}
519			return files[i].Path < files[j].Path
520		})
521		return files, nil
522	}
523	
524	func historySessionSortTime(path string, fallback time.Time) time.Time {
525		base := filepath.Base(path)
526		if len(base) >= len("20060102T150405Z") {
527			if parsed, err := time.Parse("20060102T150405Z", base[:len("20060102T150405Z")]); err == nil {
528				return parsed
529			}
530		}
531		return fallback
532	}
533	
534	func scanHistoryFile(outputDir, path string) ([]historyRecord, error) {
535		f, err := os.Open(path)
536		if err != nil {
537			return nil, err
538		}
539		defer f.Close()
540		rel, _ := filepath.Rel(outputDir, path)
541		rel = filepath.ToSlash(rel)
542		// Document-form transcripts (e.g. opencode: one pretty-printed JSON
543		// document) have no individually parseable lines, so the line scanner
544		// below indexes nothing from them. Probe the first line the same way
545		// distill does and route them through the shared document parser instead.
546		if records, isDocument, err := scanDocumentHistoryFile(f, rel); err != nil {
547			return nil, err
548		} else if isDocument {
549			return records, nil
550		}
551		if _, err := f.Seek(0, io.SeekStart); err != nil { // rewind the probe read
552			return nil, err
553		}
554		scanner := bufio.NewScanner(f)
555		scanner.Buffer(make([]byte, 0, 64*1024), historyMaxLineBytes)
556		var records []historyRecord
557		lineNumber := 0
558		allowRawText := filepath.Ext(path) == ".md" || filepath.Ext(path) == ".txt"
559		for scanner.Scan() {
560			lineNumber++
561			text := strings.TrimSpace(scanner.Text())
562			if text == "" {
563				continue
564			}
565			// Apply the cheap keyword fast-path BEFORE the JSON decode: most transcript
566			// lines are irrelevant to indexing, so on a large history this skips the
567			// per-line Unmarshal for the majority of records.
568			if !historyLineMayContainIndexedContent(text) {
569				continue
570			}
571			// Decode at most once for the narrative pass. Only transcript records are
572			// JSON objects, so skip the decode for raw .md/.txt lines that can't be one
573			// (cheap leading-'{' check); those fall through to the raw-text path.
574			var fragments []historyFragment
575			parsedOK := false
576			if strings.HasPrefix(text, "{") {
577				var obj map[string]any
578				if json.Unmarshal([]byte(text), &obj) == nil {
579					fragments = extractHistoryJSONFragments(obj)
580					parsedOK = true
581				}
582			}
583			if !parsedOK && allowRawText {
584				fragments = []historyFragment{{Text: text, Source: "text"}}
585			}
586			for _, fragment := range fragments {
587				fragment.Text = strings.TrimSpace(fragment.Text)
588				if fragment.Text == "" {
589					continue
590				}
591				for _, kind := range classifyHistoryFragment(fragment) {
592					records = append(records, historyRecord{
593						ID:      historyRecordID(rel, lineNumber, kind, fragment.Text),
594						Kind:    kind,
595						Path:    rel,
596						Line:    lineNumber,
597						Summary: truncateString(cleanHistorySummary(fragment.Text), 700),
598						Terms:   historyTerms(fragment.Text),
599					})
600				}
601			}
602		}
603		return records, scanner.Err()
604	}
605	
606	// scanDocumentHistoryFile detects and indexes a document-form transcript (see
607	// parseDocumentConversation). isDocument=false means the file is line-oriented
608	// (or not a transcript at all) and the caller's line scanner should handle it
609	// after rewinding past the probe read. Mirrors the JSONL indexing policy:
610	// assistant text is narrative, user turns are skipped; record lines anchor to
611	// the document line each message object opens on.
612	func scanDocumentHistoryFile(f *os.File, rel string) (records []historyRecord, isDocument bool, err error) {
613		probe := make([]byte, 4096)
614		n, readErr := f.Read(probe)
615		if readErr != nil && readErr != io.EOF {
616			return nil, false, readErr
617		}
618		firstLine, _, _ := strings.Cut(strings.TrimSpace(string(probe[:n])), "\n")
619		if !strings.HasPrefix(firstLine, "{") || json.Valid([]byte(firstLine)) {
620			return nil, false, nil // JSONL or non-JSON: the line scanner's job
621		}
622		data, err := safeReadAll(io.MultiReader(bytes.NewReader(probe[:n]), f), maxDocumentTranscriptBytes, "document transcript "+rel)
623		if err != nil {
624			return nil, false, err
625		}
626		messages, ok := parseDocumentConversation(string(data))
627		if !ok {
628			return nil, false, nil
629		}
630		for _, message := range messages {
631			if message.Role != "assistant" || message.Text == "" {
632				continue
633			}
634			fragment := historyFragment{Text: message.Text, Source: "assistant_message"}
635			for _, kind := range classifyHistoryFragment(fragment) {
636				records = append(records, historyRecord{
637					ID:      historyRecordID(rel, message.Line, kind, fragment.Text),
638					Kind:    kind,
639					Path:    rel,
640					Line:    message.Line,
641					Summary: truncateString(cleanHistorySummary(fragment.Text), 700),
642					Terms:   historyTerms(fragment.Text),
643				})
644			}
645		}
646		return records, true, nil
647	}
