649	// extractHistoryJSONFragments returns the indexable fragments of one
650	// transcript record: the kind-specific extraction (decisions, validations,
651	// tool calls, …) plus — when the record is a real user turn — a
652	// "user_prompt" fragment that classifies as a request record.
653	//
654	// Request records were extracted in scan-cache v2, removed in v3 ("measured
655	// noise in general ranking, and no surface queried them"), and re-introduced
656	// in v4: two Phase 2 consumers now need them — `brief --handoff` (a session's
657	// opening request) and the history eval's midtask stratum (follow-up
658	// questions as queries). The v3 noise concern remains addressed the way it
659	// always was: both rankers exclude kind=request from general ranking; the
660	// records exist for trajectory surfaces, not retrieval.
661	func extractHistoryJSONFragments(obj map[string]any) []historyFragment {
662		fragments := extractHistoryRecordFragments(obj)
663		// transcriptUserText handles all four transcript dialects (codex
664		// response_item/event_msg, Claude user, pi message); wrapper injections
665		// (environment context, caveats) are filtered with the same predicate
666		// every other request consumer uses.
667		if text := strings.TrimSpace(transcriptUserText(obj)); text != "" && !isWrapperRequest(text) {
668			fragments = append(fragments, historyFragment{Text: text, Source: "user_prompt"})
669		}
670		return fragments
671	}
