673	func extractHistoryRecordFragments(obj map[string]any) []historyFragment {
674		recordType := jsonString(obj["type"])
675		payload := jsonMap(obj["payload"])
676		switch recordType {
677		case "session_meta", "turn_context", "permission-mode":
678			return nil
679		case "agent_message":
680			return stringFragment(obj["message"], "assistant_message")
681		case "event_msg":
682			return extractCodexEventFragments(payload)
683		case "response_item":
684			return extractCodexResponseFragments(payload)
685		case "assistant":
686			return extractClaudeMessageFragments(obj, "assistant")
687		case "user":
688			return extractClaudeToolResultFragments(obj)
689		case "message":
690			// pi wraps every turn as {"type":"message","message":{role,content}}.
691			// Without this case the default branch's jsonString(obj["message"]) is
692			// "" for a map, so pi sessions indexed to nothing (the same blind spot
693			// distillConversationText covers for distill). Mirror the Claude
694			// routing: assistant text is narrative, toolResult content can carry
695			// code facts, user turns are skipped (as for codex user_message).
696			message := jsonMap(obj["message"])
697			switch jsonString(message["role"]) {
698			case "assistant":
699				return extractContentFragments(message["content"], "assistant_message")
700			case "toolResult":
701				return extractToolResultFacts(distillTextBlocks(message["content"]))
702			default:
703				return nil
704			}
705		case "progress":
706			return nil
707		default:
708			if message := jsonString(obj["message"]); message != "" {
709				return []historyFragment{{Text: message, Source: "message"}}
710			}
711			return nil
712		}
713	}
