783	func extractContentFragments(content any, source string) []historyFragment {
784		switch value := content.(type) {
785		case string:
786			return []historyFragment{{Text: value, Source: source}}
787		case []any:
788			var fragments []historyFragment
789			for _, item := range value {
790				block := jsonMap(item)
791				if len(block) == 0 {
792					if text := fmt.Sprint(item); strings.TrimSpace(text) != "" {
793						fragments = append(fragments, historyFragment{Text: text, Source: source})
794					}
795					continue
796				}
797				blockType := jsonString(block["type"])
798				switch blockType {
799				case "tool_use":
800					name := jsonString(block["name"])
801					text := strings.TrimSpace(name + " " + compactJSONValue(block["input"]))
802					fragments = append(fragments, historyFragment{Text: text, Source: historyToolCallSource(name)})
803					fragments = append(fragments, extractToolResultFacts(text)...)
804				case "tool_result":
805					fragments = append(fragments, extractToolResultFacts(firstNonEmptyString(block["content"], block["text"]))...)
806				default:
807					if text := firstNonEmptyString(block["text"], block["input_text"], block["output_text"], block["content"]); text != "" {
808						fragments = append(fragments, historyFragment{Text: text, Source: source})
809					}
810				}
811			}
812			return fragments
813		default:
814			return nil
815		}
816	}
