818	func extractToolResultFacts(text string) []historyFragment {
819		text = strings.TrimSpace(text)
820		if text == "" || !historyTextHasCodeFactSignal(text) {
821			return nil
822		}
823		lines := strings.Split(text, "\n")
824		seen := map[string]struct{}{}
825		var fragments []historyFragment
826		lastEnd := -1
827		for i, line := range lines {
828			if i < lastEnd {
829				continue
830			}
831			if !historyLineHasCodeFactSignal(line) {
832				continue
833			}
834			start := max(0, i-2)
835			end := min(len(lines), i+4)
836			snippet := cleanHistoryCodeFactSnippet(cleanHistorySummary(strings.Join(lines[start:end], " ")))
837			if snippet == "" {
838				continue
839			}
840			if _, ok := seen[snippet]; ok {
841				continue
842			}
843			seen[snippet] = struct{}{}
844			fragments = append(fragments, historyFragment{Text: snippet, Source: "tool_result_fact"})
845			lastEnd = end
846			if len(fragments) >= 8 {
847				break
848			}
849		}
850		return fragments
851	}
