876	func classifyHistoryFragment(fragment historyFragment) []string {
877		lower := strings.ToLower(fragment.Text)
878		narrative := isHistoryNarrativeSource(fragment.Source)
879		tool := strings.HasPrefix(fragment.Source, "tool_call")
880		validationTool := tool && !strings.Contains(fragment.Source, "apply_patch")
881		kinds := map[string]struct{}{}
882		if fragment.Source == "user_prompt" {
883			// Request records: excluded from general ranking (measured noise);
884			// consumed by trajectory surfaces (handoff, midtask eval mining).
885			return []string{"request"}
886		}
887		if fragment.Source == "tool_result_fact" {
888			kinds["code_fact"] = struct{}{}
889		}
890		if narrative && isDecisionFragment(fragment.Source, lower) {
891			kinds["decision"] = struct{}{}
892		}
893		if narrative && containsAny(lower, "learned", "root cause", "turns out", "lesson", "failure mode", "the issue", "the bug", "found that") {
894			kinds["learning"] = struct{}{}
895		}
896		if (narrative || validationTool) && containsAny(lower, "go test", "pytest", "npm test", "mise run", "validation", "regression test", "hidden validation", "tests pass", "validated with", "ran tests") {
897			kinds["validation"] = struct{}{}
898		}
899		if narrative && isArchitectureFragment(lower) {
900			kinds["architecture"] = struct{}{}
901		}
902		if tool || (fragment.Source == "text" && containsAny(lower, "tool_use", "function_call", "apply_patch", "exec_command", "\"cmd\"", "entire brain", "git grep", "bash ", "read ", "write ")) {
903			kinds["tool_call"] = struct{}{}
904		}
905		out := make([]string, 0, len(kinds))
906		for kind := range kinds {
907			out = append(out, kind)
908		}
909		sort.Strings(out)
910		return out
911	}
