1086	func normalizeHistorySearchText(value string) string {
1087		var b strings.Builder
1088		runes := []rune(value)
1089		lastSpace := true
1090		for i, r := range runes {
1091			if unicode.IsLetter(r) || unicode.IsDigit(r) {
1092				if !lastSpace && historyCamelBoundary(runes, i) {
1093					b.WriteByte(' ')
1094				}
1095				b.WriteRune(unicode.ToLower(r))
1096				lastSpace = false
1097				continue
1098			}
1099			if !lastSpace {
1100				b.WriteByte(' ')
1101				lastSpace = true
1102			}
1103		}
1104		return strings.TrimSpace(b.String())
1105	}
1106	
1107	func historyCamelBoundary(runes []rune, index int) bool {
1108		if index <= 0 || index >= len(runes) {
1109			return false
1110		}
1111		current := runes[index]
1112		previous := runes[index-1]
1113		if !unicode.IsLetter(current) || !(unicode.IsLetter(previous) || unicode.IsDigit(previous)) || !unicode.IsUpper(current) {
1114			return false
1115		}
1116		if unicode.IsLower(previous) || unicode.IsDigit(previous) {
1117			return true
1118		}
1119		if unicode.IsUpper(previous) && index+1 < len(runes) && unicode.IsLower(runes[index+1]) {
1120			return true
1121		}
1122		return false
1123	}
