1130		text = strings.ToLower(text)
1131		if strings.Contains(text, query) {
1132			return true
1133		}
1134		normalizedText := normalizeHistorySearchText(text)
1135		normalizedQuery := normalizeHistorySearchText(query)
1136		if normalizedQuery == "" {
1137			return false
1138		}
1139		if strings.Contains(normalizedText, normalizedQuery) {
1140			return true
1141		}
1142		return false
1143	}
