1149	// historyRecordTimestamp recovers the session capture time encoded in the
1150	// exported transcript path (sessions/<branch>/YYYYMMDDThhmmssZ_...jsonl) so
1151	// callers can order records by recency and report when a record was produced.
1152	// Records sourced from non-session paths (seed/manifest) have no timestamp.
1153	func historyRecordTimestamp(path string) (time.Time, bool) {
1154		base := filepath.Base(filepath.FromSlash(path))
1155		if len(base) < 16 {
1156			return time.Time{}, false
1157		}
1158		stamp := base[:16]
1159		parsed, err := time.Parse("20060102T150405Z", stamp)
1160		if err != nil {
1161			return time.Time{}, false
1162		}
1163		return parsed.UTC(), true
1164	}
