1166	// historyRecordMatchedTerms reports which query tokens and identifiers actually
1167	// appear in a record. Returning these makes a match explainable to an agent and
1168	// turns a zero/low-signal result into an actionable "these terms hit, these did
1169	// not" diagnostic instead of an opaque miss.
1170	func historyRecordMatchedTerms(record historyRecord, query string) []string {
1171		recordText := normalizeHistorySearchText(record.Summary + " " + strings.Join(record.Terms, " ") + " " + record.Path)
1172		recordRaw := strings.ToUpper(record.Summary + " " + strings.Join(record.Terms, " ") + " " + record.Path)
1173		seen := map[string]struct{}{}
1174		var matched []string
1175		for _, term := range historyQueryTerms(query) {
1176			if strings.Contains(recordText, term) {
1177				if _, ok := seen[term]; !ok {
1178					seen[term] = struct{}{}
1179					matched = append(matched, term)
1180				}
1181			}
1182		}
1183		for _, identifier := range historyIdentifierQueryTerms(query) {
1184			if strings.Contains(recordRaw, identifier) {
1185				key := strings.ToLower(identifier)
1186				if _, ok := seen[key]; !ok {
1187					seen[key] = struct{}{}
1188					matched = append(matched, identifier)
1189				}
1190			}
1191		}
1192		return matched
1193	}
1194	
1195	func rankHistoryRecords(index historyIndex, kind, query string, limit int) []historyRecord {
1196		scored := rankHistoryRecordsScored(index, kind, query, limit, 0)
1197		records := make([]historyRecord, 0, len(scored))
1198		for _, item := range scored {
1199			records = append(records, item.Record)
1200		}
1201		return records
1202	}
1203	
1204	// rankHistoryRecordsScored ranks records and returns the scores so callers can
1205	// surface why a record matched. minMatches relaxes the term-coverage threshold
1206	// (0 = strict default, 1 = best-effort partial matching).
1207	func rankHistoryRecordsScored(index historyIndex, kind, query string, limit, minMatches int) []scoredHistoryRecord {
1208		if limit <= 0 {
1209			return nil
1210		}
1211		allowed := historyInspectKinds(kind)
1212		scored := make([]scoredHistoryRecord, 0, min(len(index.Records), limit))
1213		seen := map[string]struct{}{}
1214		for i, record := range index.Records {
1215			if len(allowed) > 0 {
1216				if _, ok := allowed[record.Kind]; !ok {
1217					continue
1218				}
1219			} else if record.Kind == "request" {
1220				// Keep user-prompt records out of general ranking (they add noise);
1221				// they surface only via the explicit `requests` kind.
1222				continue
1223			}
1224			score := historyRecordQueryScoreMin(record, query, minMatches)
1225			if score == 0 {
1226				continue
1227			}
1228			score += historyInspectKindPreference(kind, record.Kind)
1229			matchKey := normalizeHistorySearchText(record.Summary)
1230			if _, ok := seen[matchKey]; ok {
1231				continue
1232			}
1233			seen[matchKey] = struct{}{}
1234			scored = append(scored, scoredHistoryRecord{Record: record, Score: score, Order: i})
1235		}
1236		sort.Slice(scored, func(i, j int) bool {
1237			left, right := scored[i], scored[j]
1238			if left.Score != right.Score {
1239				return left.Score > right.Score
1240			}
1241			// Among equally-scored records, prefer the most recent session so
1242			// "what is the current state of X" surfaces the latest decision first
1243			// instead of an arbitrary older one.
1244			leftTime, leftOK := historyRecordTimestamp(left.Record.Path)
1245			rightTime, rightOK := historyRecordTimestamp(right.Record.Path)
1246			if leftOK && rightOK && !leftTime.Equal(rightTime) {
1247				return leftTime.After(rightTime)
1248			}
1249			if leftOK != rightOK {
1250				return leftOK
1251			}
1252			if historyKindRank(left.Record.Kind) != historyKindRank(right.Record.Kind) {
1253				return historyKindRank(left.Record.Kind) > historyKindRank(right.Record.Kind)
1254			}
1255			if left.Record.Path != right.Record.Path {
1256				return left.Record.Path > right.Record.Path
1257			}
1258			if left.Record.Line != right.Record.Line {
1259				return left.Record.Line < right.Record.Line
1260			}
1261			return left.Order < right.Order
1262		})
1263		if len(scored) > limit {
1264			scored = scored[:limit]
1265		}
1266		return scored
1267	}
1268	
1269	func historyRecordQueryScore(record historyRecord, query string) int {
1270		return historyRecordQueryScoreMin(record, query, 0)
1271	}
1272	
1273	// historyRecordQueryScoreMin scores a record against a query. minMatches
1274	// overrides the default term-coverage threshold: pass 0 for the strict default
1275	// (precise specialist lookups) or 1 to accept best-effort partial matches for
1276	// natural-language questions that would otherwise return nothing.
1277	func historyRecordQueryScoreMin(record historyRecord, query string, minMatches int) int {
1278		score := 0
1279		if historyRecordMatchesQuery(record, query) {
1280			score += 200
1281		}
1282		terms := historyQueryTerms(query)
1283		identifiers := historyIdentifierQueryTerms(query)
1284		if len(terms) == 0 && len(identifiers) == 0 {
1285			return score
1286		}
1287		recordText := normalizeHistorySearchText(record.Summary + " " + strings.Join(record.Terms, " ") + " " + record.Path)
1288		recordRaw := strings.ToUpper(record.Summary + " " + strings.Join(record.Terms, " ") + " " + record.Path)
1289		recordTerms := normalizeHistorySearchText(strings.Join(record.Terms, " "))
1290		matches := 0
1291		for _, term := range terms {
1292			if strings.Contains(recordText, term) {
1293				matches++
1294				score += 10
1295				if strings.Contains(recordTerms, term) {
1296					score += 5
1297				}
1298			}
1299		}
1300		identifierMatches := 0
1301		for _, identifier := range identifiers {
1302			if strings.Contains(recordRaw, identifier) {
1303				identifierMatches++
1304				score += 90
1305			}
1306		}
1307		effectiveMatches := matches + identifierMatches
1308		requiredTermCount := len(terms)
1309		if requiredTermCount == 0 {
1310			requiredTermCount = len(identifiers)
1311		}
1312		required := historyRequiredQueryMatches(requiredTermCount)
1313		if minMatches > 0 && minMatches < required {
1314			required = minMatches
1315		}
1316		if effectiveMatches < required {
1317			if score < 200 {
1318				return 0
1319			}
1320			return score + historyKindRank(record.Kind)
1321		}
1322		score += effectiveMatches * 2
1323		if len(terms) > 0 && matches >= len(terms) {
1324			score += 30
1325		}
1326		score += historyRecordEvidenceScore(record, matches, identifierMatches)
1327		score += historyKindRank(record.Kind)
1328		return score
1329	}
1330	
1331	func historyRecordEvidenceScore(record historyRecord, termMatches, identifierMatches int) int {
1332		text := record.Summary + " " + strings.Join(record.Terms, " ") + " " + record.Path
1333		lower := strings.ToLower(text)
1334		score := 0
1335		pathLower := strings.ToLower(record.Path)
1336		if pathLower == "manifest.json" || strings.HasPrefix(pathLower, "seed/") {
1337			score -= 200
1338		}
1339		if record.Kind == "code_fact" {
1340			score += 35
1341		}
1342		if containsAny(lower, "diff --git", "+++ b/", "--- a/", "@@", "apply_patch", "unified_diff") {
1343			score += 40
1344		}
1345		if containsAny(lower, "packages/", "internal/", "cmd/", "src/", "apps/", ".go", ".ts", ".tsx", ".js", ".py", ".rs") {
1346			score += 20
1347		}
1348		if containsAny(lower, "metadata.step", "invalid_type", "metadata values must be strings", "metadata value") {
1349			score += 80
1350		}
1351		if containsAny(lower, "stopped chaining", "self-contained perception", "self-contained browser", "previous_response_id") &&
1352			containsAny(lower, "agentic", "browser", "chrome") {
1353			score += 90
1354		}
1355		if containsAny(lower, "openai docs", "responses api supports", "same-thread continuity", "conversations api") &&
1356			!containsAny(lower, "agentic", "browser", "chrome") {
1357			score -= 60
1358		}
1359		if identifierMatches > 0 {
1360			score += 20 * identifierMatches
1361			if containsAny(lower, "diff --git", "+++ b/", "apply_patch", "unified_diff") {
1362				score += 25
1363			}
1364		}
1365		if termMatches > 1 && containsAny(lower, "test", "validation", "regression", "contract", "invariant") {
1366			score += 12
1367		}
1368		if containsAny(lower, "start by running:", "entire doctor", "entire status --detailed", "entire session current", "entire checkpoint list") {
1369			score -= 120
1370		}
1371		if record.Kind == "tool_call" && !containsAny(lower, "apply_patch", "diff --git", "unified_diff") {
1372			score -= 20
1373		}
1374		if len(record.Summary) > 2500 && !containsAny(lower, "diff --git", "+++ b/", "apply_patch", "unified_diff") {
1375			score -= 25
1376		}
1377		return score
1378	}
1379	
1380	func historyInspectKindPreference(queryKind, recordKind string) int {
1381		switch queryKind {
1382		case "architecture":
1383			switch recordKind {
1384			case "architecture":
1385				return 120
1386			case "decision":
1387				return 80
1388			case "learning":
1389				return 40
1390			default:
1391				return 0
1392			}
1393		default:
1394			return 0
1395		}
1396	}
1397	
1398	func historyRequiredQueryMatches(termCount int) int {
1399		switch {
1400		case termCount <= 1:
1401			return 1
1402		case termCount <= 3:
1403			return 2
1404		default:
1405			return 3
1406		}
1407	}
1408	
1409	func historyKindRank(kind string) int {
1410		switch kind {
1411		case "decision":
1412			return 40
1413		case "request":
1414			return 34
1415		case "architecture":
1416			return 32
1417		case "code_fact":
1418			return 30
1419		case "learning":
1420			return 26
1421		case "validation":
1422			return 18
1423		case "tool_call":
1424			return 4
1425		default:
1426			return 1
1427		}
1428	}
1429	
1430	func historyQueryTerms(query string) []string {
1431		normalized := normalizeHistorySearchText(query)
1432		seen := map[string]struct{}{}
1433		var terms []string
1434		for _, term := range strings.Fields(normalized) {
1435			if historyQueryStopword(term) {
1436				continue
1437			}
1438			if len(term) < 3 && !historyShortQueryTerm(term) {
1439				continue
1440			}
1441			if _, ok := seen[term]; ok {
1442				continue
1443			}
1444			seen[term] = struct{}{}
1445			terms = append(terms, term)
1446		}
1447		return terms
1448	}
1449	
1450	// historyQueryAllTerms returns the union of word tokens and identifier tokens a
1451	// query reduces to after stopword removal. Surfacing these lets an agent see
1452	// exactly what the brain searched for, so a thin or empty result is debuggable
1453	// (e.g. an over-specific phrase reduced to one weak term) instead of opaque.
1454	func historyQueryAllTerms(query string) []string {
1455		seen := map[string]struct{}{}
1456		var all []string
1457		for _, term := range historyQueryTerms(query) {
1458			if _, ok := seen[term]; !ok {
1459				seen[term] = struct{}{}
1460				all = append(all, term)
1461			}
1462		}
1463		for _, identifier := range historyIdentifierQueryTerms(query) {
1464			key := strings.ToLower(identifier)
1465			if _, ok := seen[key]; !ok {
1466				seen[key] = struct{}{}
1467				all = append(all, identifier)
1468			}
1469		}
1470		return all
1471	}
1472	
1473	func historyIdentifierQueryTerms(query string) []string {
1474		seen := map[string]struct{}{}
1475		var terms []string
1476		for _, candidate := range strings.FieldsFunc(query, func(r rune) bool {
1477			return !(unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_')
1478		}) {
1479			candidate = strings.Trim(candidate, "_")
1480			if candidate == "" {
1481				continue
1482			}
1483			upper := strings.ToUpper(candidate)
1484			if !strings.Contains(upper, "_") && !historyIdentifierLike(candidate) {
1485				continue
1486			}
1487			if historyQueryStopword(strings.ToLower(upper)) {
1488				continue
1489			}
1490			if _, ok := seen[upper]; ok {
1491				continue
1492			}
1493			seen[upper] = struct{}{}
1494			terms = append(terms, upper)
1495		}
1496		return terms
1497	}
1498	
1499	func historyIdentifierLike(candidate string) bool {
1500		if len(candidate) < 3 {
1501			return false
1502		}
1503		hasUpper := false
1504		hasLower := false
1505		hasDigit := false
1506		hasInternalUpper := false
1507		for i, r := range candidate {
1508			switch {
1509			case unicode.IsUpper(r):
1510				hasUpper = true
1511				if i > 0 {
1512					hasInternalUpper = true
1513				}
1514			case unicode.IsLower(r):
1515				hasLower = true
1516			case unicode.IsDigit(r):
1517				hasDigit = true
1518			}
1519		}
1520		if hasUpper && !hasLower {
1521			return true
1522		}
1523		if hasInternalUpper && hasLower {
1524			return true
1525		}
1526		return hasDigit && (hasUpper || hasLower)
1527	}
1528	
1529	func historyShortQueryTerm(term string) bool {
1530		switch term {
1531		case "go", "ci", "pr", "ui", "id", "lc":
1532			return true
1533		default:
1534			return false
1535		}
1536	}
1537	
1538	// genericQueryStopwords are generic English fillers and generic task verbs with
1539	// no retrieval signal. It is the SINGLE source of truth shared by every query
1540	// tokenizer in the package — history/semantic specialist search
1541	// (historyQueryStopword) and brain-brief filename matching
1542	// (brainBriefFileMatchTerms) — so the common list never drifts between the two.
1543	// Each call site layers only its own domain-specific noise words on top; those
1544	// legitimately differ (e.g. "regression"/"preserve" are noise for free-text
1545	// history search but valid filename-match terms like regression.go for brief).
1546	var genericQueryStopwords = map[string]bool{
1547		"and": true, "are": true, "before": true, "but": true, "can": true,
1548		"did": true, "does": true, "fix": true, "for": true, "from": true,
1549		"has": true, "have": true, "how": true, "into": true, "its": true,
1550		"make": true, "must": true, "need": true, "new": true, "not": true,
1551		"run": true, "runs": true, "should": true, "than": true, "that": true,
1552		"the": true, "then": true, "this": true, "use": true, "via": true,
1553		"want": true, "what": true, "when": true, "where": true, "which": true,
1554		"why": true, "with": true, "would": true,
1555	}
1556	
1557	func historyQueryStopword(term string) bool {
1558		if genericQueryStopwords[term] {
1559			return true
1560		}
1561		// History/semantic-search-specific noise words layered on the generic set:
1562		// natural-language filler plus domain verbs/nouns ("regression", "preserve",
1563		// "restore", ...) that carry no signal for a free-text record search.
1564		switch term {
1565		case "a", "an", "as", "at", "be", "been", "by", "current", "do",
1566			"during", "existing", "in", "is", "it", "keep", "local", "of", "on",
1567			"only", "or", "other", "previous", "prior", "preserve", "regression",
1568			"restore", "same", "task", "to", "without":
1569			return true
1570		case "behavior", "entire", "fresh", "parent", "setting", "value", "values":
1571			return true
1572		case "done", "over", "instead", "we", "our", "could", "about":
1573			return true
1574		default:
1575			return false
1576		}
1577	}
1578	
1579	func loadBrainHistoryIndex(brainDir string, source *historySourceManifest) (historyIndex, error) {
1580		if source == nil || source.IndexPath == "" {
1581			return historyIndex{}, errors.New("history index missing; run `entire brain refresh`")
1582		}
1583		clean, err := validateHistoryIndexPath(source.IndexPath)
1584		if err != nil {
1585			return historyIndex{}, err
1586		}
1587		if err := rejectSymlinkPathComponents(brainDir, clean); err != nil {
1588			return historyIndex{}, err
1589		}
1590		data, err := os.ReadFile(filepath.Join(brainDir, clean))
1591		if err != nil {
1592			return historyIndex{}, err
1593		}
1594		var index historyIndex
1595		if err := json.Unmarshal(data, &index); err != nil {
1596			return historyIndex{}, err
1597		}
1598		return index, nil
1599	}
1600	
1601	func validateHistoryIndexPath(indexPath string) (string, error) {
1602		clean := filepath.Clean(filepath.FromSlash(indexPath))
1603		cleanSlash := filepath.ToSlash(clean)
1604		if cleanSlash != indexPath {
1605			return "", fmt.Errorf("history index_path must be canonical: %s", indexPath)
1606		}
1607		if strings.HasPrefix(clean, ".."+string(filepath.Separator)) || filepath.IsAbs(clean) || cleanSlash != historyIndexPath {
1608			return "", fmt.Errorf("history index_path is unsafe: %s", indexPath)
1609		}
1610		return clean, nil
1611	}
