10	// retrieve.go is the unified retrieval layer behind the qmd-inspired verbs
11	// (search/vsearch/query). It ranks across the brain's text layers — facts,
12	// history, docs — and merges the per-source ranked lists with RRF. Each layer
13	// keeps its own best ranker; RRF fuses them by rank so their incomparable raw
14	// scores don't fight.
15	
16	type unifiedResult struct {
17		Source               string            `json:"source"` // fact | fact-review | history | doc | consolidation | theme | workspace_pattern | workspace_graph
18		ID                   string            `json:"id"`     // prefixed, addressable by get/multi-get
19		Path                 string            `json:"path,omitempty"`
20		Heading              string            `json:"heading,omitempty"`
21		Line                 int               `json:"line,omitempty"`
22		Text                 string            `json:"text"`
23		Score                float64           `json:"score,omitempty"` // omitted for unranked results (get/multi-get); RRF scores are always > 0
24		VerificationRequired bool              `json:"verification_required,omitempty"`
25		Caveats              []retrievalCaveat `json:"caveats,omitempty"`
26		RelatedIDs           []string          `json:"related_ids,omitempty"`
27	}
28	
29	type retrievalMode int
30	
31	const (
32		modeLexical retrievalMode = iota // search
33		modeVector                       // vsearch
34		modeHybrid                       // query
35	)
36	
37	func embedQueryWith(e Embedder, q string) []float32 {
38		if qe, ok := e.(queryEmbedder); ok {
39			return qe.EmbedQuery(q)
40		}
41		return e.Embed(q)
42	}
43	
44	// retrieveUnified ranks across facts + history + docs. Lexical (search) and
45	// hybrid (query) include all three; vector (vsearch) covers facts + docs always,
46	// and history only behind the fusion gate (a fusion-eligible embedder plus the
47	// brain_cgo vec0 store with refresh-built vectors — see history_vec.go). The
48	// gate exists because Model2Vec on history is a measured closed negative and
49	// embedding hundreds of thousands of records per query is hours of work that
50	// belongs in refresh. Missing layers are skipped, not errors.
51	func retrieveUnified(repoDir, brainDir, branch, query string, limit int, mode retrievalMode) ([]unifiedResult, error) {
52		if limit <= 0 {
53			limit = 10
54		}
55		// Preserve the existing 2x per-layer candidate budget. The facts arm adds a
56		// bounded collapse reserve before applying trust state, so unrelated
57		// history/doc RRF candidates never change merely because a proposal entered
58		// the review queue without converting the entire fact corpus on every query.
59		candidateLimit := limit * 2
60		if candidateLimit < limit { // integer overflow guard for unreasonable inputs
61			candidateLimit = limit
62		}
63		// loadFacts surfaces corrupt NDJSON as a hard error; propagate it rather than
64		// presenting a broken store as "no results".
65		all, err := loadFacts(brainDir, branch)
66		if err != nil {
67			return nil, err
68		}
69		active := make([]factRecord, 0, len(all))
70		for _, f := range all {
71			if f.Status == factStatusActive {
72				active = append(active, f)
73			}
74		}
75		proposals, proposalsErr := loadFactProposals(brainDir, branch)
76		var e Embedder
77		if mode != modeLexical {
78			e = defaultEmbedder()
79		}
80	
81		var lists [][]unifiedResult
82	
83		// Facts.
84		if len(active) > 0 {
85			factLimit := min(len(active), candidateLimit)
86			if proposalsErr == nil {
87				factLimit = guardedFactCandidateLimit(active, proposals, candidateLimit)
88			}
89			var factResults []unifiedResult
90			switch mode {
91			case modeLexical:
92				factResults = factsToUnified(rankFacts(active, query, factLimit, false))
93			case modeVector:
94				if e != nil {
95					// Pass the full set: factsVectorRanked ranks active facts but caches
96					// (and prunes) every present fact, matching the reranker's shared store.
97					factResults = factsToUnified(factsVectorRanked(
98						brainDir, branch, all, query, e, factLimit,
99					))
100				}
101			case modeHybrid:
102				var rr *semanticReranker
103				if e != nil {
104					rr = newSemanticRerankerForBranch(e, brainDir, branch)
105				}
106				factResults = factsToUnified(rankFactsFused(active, query, factLimit, false, rr))
107				if rr != nil {
108					rr.retain(all) // keep every present fact's vector; prune only departed facts (matches recall/brief)
109					_ = rr.flush()
110				}
111			}
112			if proposalsErr == nil {
113				factResults = guardUnifiedFactResults(repoDir, all, proposals, factResults, candidateLimit)
114			} else {
115				factResults = guardUnifiedFactResults(repoDir, all, nil, factResults, candidateLimit)
116				factResults = annotateProposalStateUnavailable(factResults)
117			}
118			if len(factResults) > 0 {
119				lists = append(lists, factResults)
120			}
121		}
122	
123		// History — BM25 (lexical / hybrid), plus the gated semantic arm (hybrid /
124		// vector; see history_vec.go). The FTS index is an optimization, never
125		// load-bearing (see history_fts.go): on a build/open/query failure fall
126		// back to the in-memory substring scorer. But a corrupt manifest, or a history
127		// index the manifest declares yet is missing/unreadable, is a real storage
128		// problem — surface it rather than returning silently-incomplete results. A
129		// brain with no history source (nil) is legitimately skipped.
130		historySem := historySemanticEmbedder(e)
131		if mode != modeVector || historySem != nil {
132			manifest, err := loadBrainManifest(brainDir)
133			if err != nil {
134				return nil, err
135			}
136			if manifest.Sources != nil && manifest.Sources.History != nil {
137				index, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History)
138				if err != nil {
139					return nil, fmt.Errorf("load history index: %w", err)
140				}
141				var lexicalHistoryIDs map[string]struct{}
142				if mode != modeVector {
143					historyCandidateLimit := candidateLimit * 3
144					if historyCandidateLimit < candidateLimit {
145						historyCandidateLimit = candidateLimit
146					}
147					scored, ok := rankHistoryViaFTS(brainDir, index, "history", query, historyCandidateLimit)
148					if !ok {
149						scored = rankHistoryRecordsScored(index, "history", query, historyCandidateLimit, 0)
150					}
151					scored = filterHistoryRetrievalSelfEchoes(scored, query)
152					if len(scored) > candidateLimit {
153						scored = scored[:candidateLimit]
154					}
155					if len(scored) > 0 {
156						lexicalHistoryIDs = make(map[string]struct{}, len(scored))
157						for _, record := range scored {
158							lexicalHistoryIDs[record.Record.ID] = struct{}{}
159						}
160						lists = append(lists, historyToUnified(scored))
161					}
162				}
163				if mode != modeLexical && historySem != nil {
164					// Independently ranked history lists: the global RRF merge fuses
165					// BM25 and cosine, then gives calibrated term-disjoint evidence a
166					// second vote without triple-counting lexical hits.
167					scores := historySemanticScores(
168						brainDir, historySem, query, candidateLimit, mode == modeHybrid,
169					)
170					var sem historyVectorRanks
171					if mode == modeVector {
172						sem.ranked = rankHistorySemantic(index, scores, candidateLimit)
173					} else {
174						sem = rankHistorySemanticHybridRanks(index, scores, candidateLimit, lexicalHistoryIDs)
175					}
176					if len(sem.ranked) > 0 {
177						lists = append(lists, historyToUnified(sem.ranked))
178					}
179					if len(sem.calibratedSemanticOnly) > 0 {
180						lists = append(lists, historyToUnified(sem.calibratedSemanticOnly))
181					}
182				}
183			}
184		}
185	
186		// Docs — lexical (search/query) and/or vector (vsearch/query). In hybrid mode
187		// docs join BOTH arms, mirroring facts. A never-built doc index is skipped; a
188		// corrupt/unreadable one is a real storage problem and is surfaced.
189		docIdx, derr := loadDocIndex(brainDir)
190		switch {
191		case derr == nil && len(docIdx.Records) > 0:
192			var lexicalDocIDs map[string]struct{}
193			if mode != modeVector {
194				// FTS is an optimization, never load-bearing: fall back to the in-memory
195				// lexical scorer so docs don't vanish when the doc FTS index can't open.
196				scored, ok := rankDocsViaFTS(brainDir, docIdx, query, candidateLimit)
197				if !ok {
198					scored = rankDocsLexical(docIdx, query, candidateLimit)
199				}
200				if len(scored) > 0 {
201					lexicalDocIDs = make(map[string]struct{}, len(scored))
202					for _, record := range scored {
203						lexicalDocIDs[record.Record.ID] = struct{}{}
204					}
205					lists = append(lists, docsToUnified(scored))
206				}
207			}
208			if mode != modeLexical && e != nil {
209				vectorRanks := docsVectorRanked(
210					brainDir, docIdx, query, e, candidateLimit, mode == modeHybrid, lexicalDocIDs,
211				)
212				if len(vectorRanks.ranked) > 0 {
213					lists = append(lists, vectorRanks.ranked)
214				}
215				if len(vectorRanks.calibratedSemanticOnly) > 0 {
216					lists = append(lists, vectorRanks.calibratedSemanticOnly)
217				}
218			}
219		case derr != nil && !os.IsNotExist(derr):
220			return nil, fmt.Errorf("load doc index: %w", derr)
221		}
222	
223		return rrfMergeUnified(lists, limit), nil
224	}
