226	func filterHistoryRetrievalSelfEchoes(scored []scoredHistoryRecord, query string) []scoredHistoryRecord {
227		needle := strings.ToLower(strings.TrimSpace(query))
228		if needle == "" {
229			return scored
230		}
231		out := scored[:0]
232		for _, item := range scored {
233			kind := strings.ToLower(strings.TrimSpace(item.Record.Kind))
234			summary := strings.ToLower(item.Record.Summary)
235			brainInvocation := strings.Contains(summary, "entire brain search") ||
236				strings.Contains(summary, "entire brain query") ||
237				strings.Contains(summary, "entire brain brief") ||
238				strings.Contains(summary, "brain_search") ||
239				strings.Contains(summary, "brain_query") ||
240				strings.Contains(summary, "brain_brief")
241			if kind == "tool_call" && brainInvocation && strings.Contains(summary, needle) {
242				continue
243			}
244			out = append(out, item)
245		}
246		return out
247	}
248	
249	// factsVectorRanked ranks active facts by cosine. facts is the full present set
250	// (all statuses): active facts are ranked, but every present fact is embedded and
251	// retained in the shared cache so this path keeps the same vectors the recall/brief
252	// reranker does — and departed facts are pruned so the on-disk cache stays bounded.
253	func factsVectorRanked(
254		brainDir, branch string,
255		facts []factRecord,
256		query string,
257		e Embedder,
258		limit int,
259	) []factRecord {
260		// An empty query vector means the embedder is unavailable (e.g. Ollama down).
261		// Return no semantic results rather than an arbitrary top-N: every cosine
262		// would be 0 and the sort would just echo input order. A wrong-dimension
263		// query also fails closed before the cache is inspected: it must not make
264		// valid document vectors look corrupt and trigger a destructive rebuild.
265		qv := embedQueryWith(e, query)
266		if e.Dim() <= 0 || len(qv) != e.Dim() || !vectorHasMagnitude(qv) {
267			return nil
268		}
269		store := newVectorStore(brainDir, branch, factEmbeddingModelID(e.ID()), e.Dim())
270		cache := store.load()
271		dirty := false
272		present := make(map[string]struct{}, len(facts))
273		type sc struct {
274			rec factRecord
275			cos float64
276		}
277		scored := make([]sc, 0, len(facts))
278		for _, f := range facts {
279			present[f.ID] = struct{}{}
280			v, ok := cache[f.ID]
281			if ok && (len(v) != len(qv) || !vectorHasMagnitude(v)) {
282				// A nil value is a deletion tombstone for savePresent: it overrides
283				// any invalid entry reloaded under the write lock, then is omitted
284				// from the rewritten store if re-embedding fails.
285				cache[f.ID] = nil
286				dirty = true
287				ok = false
288			}
289			if !ok {
290				v = e.Embed(factEmbeddingText(f))
291				if len(v) == len(qv) && vectorHasMagnitude(v) {
292					cache[f.ID] = v // never cache empty/mismatched vectors
293					dirty = true
294				}
295			}
296			if f.Status != factStatusActive || len(v) != len(qv) {
297				continue // rank active facts only; skip degenerate vectors
298			}
299			if !vectorHasMagnitude(v) {
300				continue
301			}
302			scored = append(scored, sc{rec: f, cos: cosineFloat32(qv, v)})
303		}
304		if saved := pruneToPresent(cache, present); dirty || saved {
305			_ = store.savePresent(cache, present)
306		}
307		sort.Slice(scored, func(a, b int) bool { return scored[a].cos > scored[b].cos })
308		out := make([]factRecord, 0, min(limit, len(scored)))
309		for _, s := range scored {
310			out = append(out, s.rec)
311			if len(out) >= limit {
312				break
313			}
314		}
315		return out
316	}
317	
318	// pruneToPresent drops cache entries whose id is no longer in present, keeping the
319	// on-disk vector cache bounded to the current corpus. Reports whether it removed
320	// anything (so callers save even when no new vector was embedded).
321	func pruneToPresent(cache map[string][]float32, present map[string]struct{}) bool {
322		removed := false
323		for id := range cache {
324			if _, ok := present[id]; !ok {
325				delete(cache, id)
326				removed = true
327			}
328		}
329		return removed
330	}
331	
332	type documentVectorRanks struct {
333		ranked                 []unifiedResult
334		calibratedSemanticOnly []unifiedResult
335	}
336	
337	func docsVectorRanked(
338		brainDir string,
339		index docIndex,
340		query string,
341		e Embedder,
342		limit int,
343		requireRelevance bool,
344		lexicalDocIDs map[string]struct{},
345	) documentVectorRanks {
346		// Same guard as factsVectorRanked: no query vector → no doc semantic hits,
347		// not arbitrary docs ranked by all-zero cosines.
348		qv := embedQueryWith(e, query)
349		if e.Dim() <= 0 || len(qv) != e.Dim() || !vectorHasMagnitude(qv) {
350			return documentVectorRanks{}
351		}
352		store := newDocEmbedStore(brainDir, e.ID(), e.Dim())
353		cache := store.load()
354		dirty := false
355		present := make(map[string]struct{}, len(index.Records))
356		type sc struct {
357			i      int
358			cos    float64
359			vector []float32
360			keep   bool
361		}
362		scored := make([]sc, 0, len(index.Records))
363		for i, r := range index.Records {
364			present[r.ID] = struct{}{}
365			v, ok := cache[r.ID]
366			if ok && (len(v) != len(qv) || !vectorHasMagnitude(v)) {
367				cache[r.ID] = nil // persist deletion if repair fails
368				dirty = true
369				ok = false
370			}
371			if !ok {
372				v = e.Embed(r.Text)
373				if len(v) == len(qv) && vectorHasMagnitude(v) {
374					cache[r.ID] = v
375					dirty = true
376				}
377			}
378			if len(v) != len(qv) {
379				continue
380			}
381			if !vectorHasMagnitude(v) {
382				continue
383			}
384			entry := sc{i: i, cos: cosineFloat32(qv, v)}
385			if requireRelevance {
386				entry.vector = v
387			}
388			scored = append(scored, entry)
389		}
390		// Doc ids are content-derived, so any rebuild churns them; prune departed ids
391		// so the cache stays bounded to the current doc corpus.
392		if saved := pruneToPresent(cache, present); dirty || saved {
393			_ = store.savePresent(cache, present)
394		}
395		cosines := make([]float64, len(scored))
396		vectors := make([][]float32, len(scored))
397		for i := range scored {
398			cosines[i] = scored[i].cos
399			vectors[i] = scored[i].vector
400		}
401		var backgrounds []float64
402		if requireRelevance {
403			backgrounds = semanticLeaveOneOutBackgrounds(qv, vectors)
404		}
405		mask := semanticResultMask(cosines, requireRelevance, backgrounds)
406		for i := range scored {
407			scored[i].keep = mask[i]
408		}
409		sort.Slice(scored, func(a, b int) bool {
410			left := docTrustAdjustedScore(scored[a].cos, index.Records[scored[a].i].Historical)
411			right := docTrustAdjustedScore(scored[b].cos, index.Records[scored[b].i].Historical)
412			if left != right {
413				return left > right
414			}
415			return index.Records[scored[a].i].ID < index.Records[scored[b].i].ID
416		})
417		out := documentVectorRanks{
418			ranked:                 make([]unifiedResult, 0, min(limit, len(scored))),
419			calibratedSemanticOnly: make([]unifiedResult, 0),
420		}
421		for _, s := range scored {
422			_, lexical := lexicalDocIDs[index.Records[s.i].ID]
423			if !s.keep && !(requireRelevance && lexical) {
424				continue
425			}
426			result := docToUnified(index.Records[s.i])
427			if len(out.ranked) < limit {
428				out.ranked = append(out.ranked, result)
429			}
430			if requireRelevance && s.keep && !lexical && len(out.calibratedSemanticOnly) < limit {
431				out.calibratedSemanticOnly = append(out.calibratedSemanticOnly, result)
432			}
433			if len(out.ranked) >= limit && (!requireRelevance || len(out.calibratedSemanticOnly) >= limit) {
434				break
435			}
436		}
437		return out
438	}
439	
440	func factsToUnified(facts []factRecord) []unifiedResult {
441		// fact ids are already prefixed "fact:" (factRecordID); history likewise.
442		out := make([]unifiedResult, len(facts))
443		for i, f := range facts {
444			out[i] = unifiedResult{Source: "fact", ID: f.ID, Path: strings.Join(f.Paths, ","), Heading: factKindOrInferred(f), Text: f.Text}
445		}
446		return out
447	}
448	
449	func historyToUnified(scored []scoredHistoryRecord) []unifiedResult {
450		out := make([]unifiedResult, len(scored))
451		for i, s := range scored {
452			out[i] = unifiedResult{Source: "history", ID: s.Record.ID, Path: s.Record.Path, Line: s.Record.Line, Heading: s.Record.Kind, Text: s.Record.Summary}
453		}
454		return out
455	}
456	
457	func docToUnified(r docRecord) unifiedResult {
458		result := unifiedResult{Source: "doc", ID: "doc:" + r.ID, Path: r.Path, Line: r.Line, Heading: r.Heading, Text: r.Text}
459		if r.Historical {
460			result.VerificationRequired = true
461			result.Caveats = []retrievalCaveat{{
462				Kind:    retrievalCaveatHistoricalDocument,
463				Message: "This document is explicitly historical or superseded; prefer current operational documentation.",
464				Paths:   []string{r.Path},
465				Action:  "Verify against the current README and active implementation before relying on it.",
466			}}
467		}
468		return result
469	}
470	
471	func docsToUnified(scored []scoredDocRecord) []unifiedResult {
472		out := make([]unifiedResult, len(scored))
473		for i, s := range scored {
474			out[i] = docToUnified(s.Record)
475		}
476		return out
477	}
478	
479	func rrfMergeUnified(lists [][]unifiedResult, limit int) []unifiedResult {
480		fused := map[string]float64{}
481		rec := map[string]unifiedResult{}
482		for _, list := range lists {
483			for rank, r := range list {
484				fused[r.ID] += 1.0 / (rrfK + float64(rank+1))
485				if _, ok := rec[r.ID]; !ok {
486					rec[r.ID] = r
487				}
488			}
489		}
490		out := make([]unifiedResult, 0, len(rec))
491		for id, r := range rec {
492			r.Score = fused[id]
493			out = append(out, r)
494		}
495		sort.Slice(out, func(a, b int) bool {
496			if out[a].Score != out[b].Score {
497				return out[a].Score > out[b].Score
498			}
499			return out[a].ID < out[b].ID
500		})
501		if len(out) > limit {
502			out = out[:limit]
503		}
504		return out
505	}
506	
507	// getUnifiedBatch resolves prefixed ids (fact:/review:/history:/doc:/pattern:/theme:) to full records,
508	// loading each corpus at most once and indexing it by id. get/multi-get (and the
509	// MCP brain_get/brain_multi_get) route through here so resolving N ids is O(corpus
510	// + N), not O(N × corpus) — the latter rescans the full history per id and is
511	// pathological on large brains. Results preserve input order.
512	func getUnifiedBatch(repoDir, brainDir, branch string, ids []string) (found []unifiedResult, missing []string, err error) {
513		var wantFact, wantReview, wantHistory, wantDoc bool
514		for _, id := range ids {
515			switch {
516			case strings.HasPrefix(id, "fact:"):
517				wantFact = true
518			case strings.HasPrefix(id, "review:"):
519				wantReview = true
520			case strings.HasPrefix(id, "history:"):
521				wantHistory = true
522			case strings.HasPrefix(id, "doc:"):
523				wantDoc = true
524			}
525		}
526		factByID := map[string]factRecord{}
527		var reviewByID map[string]factReviewGroup
528		var reviewByFactID map[string]factReviewGroup
529		var proposalStateUnavailable bool
530		if wantFact || wantReview {
531			// Surface a corrupt facts store as an error, not a misleading "not found".
532			facts, ferr := loadFacts(brainDir, branch)
533			if ferr != nil {
534				return nil, nil, ferr
535			}
536			for _, f := range facts {
537				factByID[f.ID] = f
538			}
539			proposals, perr := loadFactProposals(brainDir, branch)
540			if perr != nil && wantReview {
541				return nil, nil, perr
542			}
543			if perr == nil {
544				reviewByID, reviewByFactID = indexFactReviewGroups(buildFactReviewGroups(facts, proposals))
545			} else {
546				proposalStateUnavailable = true
547			}
548		}
549		histByID := map[string]historyRecord{}
550		if wantHistory {
551			// A corrupt manifest, or a history index the manifest declares but that is
552			// missing/unreadable, is a real storage problem — surface it rather than
553			// reporting every history:* id as "not found". A brain with no history source
554			// (nil) legitimately has no such records, so leave histByID empty.
555			manifest, err := loadBrainManifest(brainDir)
556			if err != nil {
557				return nil, nil, err
558			}
559			if manifest.Sources != nil && manifest.Sources.History != nil {
560				index, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History)
561				if err != nil {
562					return nil, nil, fmt.Errorf("load history index: %w", err)
563				}
564				for _, r := range index.Records {
565					histByID[r.ID] = r
566				}
567			}
568		}
569		docByID := map[string]docRecord{}
570		if wantDoc {
571			// A never-built doc index is not an error (doc:* ids just report "not
572			// found"); a corrupt/unreadable one is — surface it.
573			index, err := loadDocIndex(brainDir)
574			switch {
575			case err == nil:
576				for _, r := range index.Records {
577					docByID[r.ID] = r
578				}
579			case !os.IsNotExist(err):
580				return nil, nil, fmt.Errorf("load doc index: %w", err)
581			}
582		}
583		for _, id := range ids {
584			switch {
585			case strings.HasPrefix(id, "fact:"):
586				if f, ok := factByID[id]; ok {
587					r := factsToUnified([]factRecord{f})[0]
588					if group, pending := reviewByFactID[id]; pending {
589						r = annotateExplicitFactReview(r, group)
590					}
591					r = annotateFactLocusTrust(repoDir, f, r)
592					if proposalStateUnavailable {
593						r = annotateProposalStateUnavailable([]unifiedResult{r})[0]
594					}
595					found = append(found, r)
596					continue
597				}
598			case strings.HasPrefix(id, "review:"):
599				if group, ok := reviewByID[id]; ok {
600					r := factReviewToUnified(repoDir, group)
601					// Preserve an addressable proposal alias if the group grew, including
602					// the machine-readable caveat that tells clients what to review.
603					r.ID = id
604					for i := range r.Caveats {
605						if r.Caveats[i].Kind == retrievalCaveatUnresolvedReview {
606							r.Caveats[i].ReviewID = id
607						}
608					}
609					found = append(found, r)
610					continue
611				}
612			case strings.HasPrefix(id, "history:"):
613				if r, ok := histByID[id]; ok {
614					found = append(found, historyToUnified([]scoredHistoryRecord{{Record: r}})[0])
615					continue
616				}
617			case strings.HasPrefix(id, "doc:"):
618				if r, ok := docByID[strings.TrimPrefix(id, "doc:")]; ok {
619					found = append(found, docToUnified(r))
620					continue
621				}
622			case strings.HasPrefix(id, "pattern:"):
623				// Consolidation dossier addressed by its pattern id (v2). Corpus is
624				// rebuildable/optional, so a missing corpus is "not found", not an error.
625				if r, ok := getCorpusConsolidation(brainDir, id); ok {
626					found = append(found, r)
627					continue
628				}
629			case strings.HasPrefix(id, "theme:"):
630				if r, ok := getCorpusTheme(brainDir, id); ok {
631					found = append(found, r)
632					continue
633				}
634			}
635			missing = append(missing, id)
636		}
637		return found, missing, nil
638	}
