269		rows, err := db.Query(sb.String(), args...)
270		if err != nil {
271			return nil, false
272		}
273		defer rows.Close()
274		out := make([]scoredHistoryRecord, 0, limit)
275		seen := map[string]struct{}{}
276		var topScore float64
277		for rows.Next() {
278			var order int
279			var bm float64
280			if err := rows.Scan(&order, &bm); err != nil {
281				return nil, false
282			}
283			if order < 0 || order >= len(index.Records) {
284				continue
285			}
286			// Rows arrive best-first (bm25 ascending), so the first kept row is the
287			// top score and the cutoff can stop the scan: every later row is weaker.
288			score := -bm // bm is SQLite's negated BM25 (<= 0); -bm is positive, higher = better
289			if topScore == 0 {
290				topScore = score
291			} else if score < cutoff*topScore {
292				break
293			}
294			rec := index.Records[order]
295			key := normalizeHistorySearchText(rec.Summary)
296			if _, ok := seen[key]; ok {
297				continue
298			}
299			seen[key] = struct{}{}
300			out = append(out, scoredHistoryRecord{Record: rec, Score: int(score*1000 + 0.5), Order: order})
301			if len(out) >= limit {
302				break
303			}
304		}
305		if rows.Err() != nil {
306			return nil, false
307		}
308		return out, true
309	}
