269	// retrievalResultExcerpt centers a compact result on the densest query-term
270	// window. Ranked retrieval is a locator surface; get/multi-get own full bodies.
271	func retrievalResultExcerpt(value, query string, maxBytes int) string {
272		text := strings.Join(strings.Fields(value), " ")
273		if maxBytes <= 0 || text == "" {
274			return ""
275		}
276		if len(text) <= maxBytes {
277			return text
278		}
279		lower, originalOffsets := foldedTextOffsets(text)
280		terms := semanticQueryTokens(query)
281		bestStart, bestScore := 0, -1
282		for _, anchor := range terms {
283			for searchAt := 0; searchAt < len(lower); {
284				rel := strings.Index(lower[searchAt:], anchor)
285				if rel < 0 {
286					break
287				}
288				at := searchAt + rel
289				originalAt := originalOffsets[min(at, len(originalOffsets)-1)]
290				start := max(0, originalAt-maxBytes/3)
291				end := min(len(text), start+maxBytes)
292				for start > 0 && !utf8.RuneStart(text[start]) {
293					start--
294				}
295				for end < len(text) && !utf8.RuneStart(text[end]) {
296					end++
297				}
298				window := strings.ToLower(text[start:end])
299				score := 0
300				for _, term := range terms {
301					if strings.Contains(window, term) {
302						score += len(term)
303					}
304				}
305				if score > bestScore {
306					bestStart, bestScore = start, score
307				}
308				searchAt = at + len(anchor)
309			}
310		}
311		start := bestStart
312		end := min(len(text), start+maxBytes)
313		for start > 0 && !utf8.RuneStart(text[start]) {
314			start--
315		}
316		for end < len(text) && !utf8.RuneStart(text[end]) {
317			end++
318		}
319		excerpt := strings.TrimSpace(text[start:end])
320		if start > 0 {
321			excerpt = "..." + excerpt
322		}
323		if end < len(text) {
324			excerpt += "..."
325		}
326		return excerpt
327	}
328	
329	// foldedTextOffsets returns a lowercase search string plus a byte-offset map
330	// back to the original UTF-8 text. Unicode case folding can change byte length
331	// (for example, K -> k), so offsets into strings.ToLower(text) must never be
332	// applied directly to text.
333	func foldedTextOffsets(text string) (string, []int) {
334		var folded strings.Builder
335		offsets := make([]int, 0, len(text)+1)
336		for originalAt, r := range text {
337			lowerRune := strings.ToLower(string(r))
338			folded.WriteString(lowerRune)
339			for range []byte(lowerRune) {
340				offsets = append(offsets, originalAt)
341			}
342		}
343		offsets = append(offsets, len(text))
344		return folded.String(), offsets
345	}
