354			Args:  cobra.ExactArgs(1),
355			RunE: func(cmd *cobra.Command, args []string) error {
356				wantJSON, err := outputWantsJSON(jsonOut, format)
357				if err != nil {
358					return err
359				}
360				return runGet(cmd.Context(), cmd, opts, []string{args[0]}, branch, wantJSON, "get")
361			},
362		}
363		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit machine-readable JSON")
364		cmd.Flags().StringVar(&format, "format", "", "Output format: json or cli (QMD-style alias for --json)")
365		cmd.Flags().StringVar(&branch, "branch", "", "Branch for facts (default: current)")
366		return cmd
367	}
