369	func newMultiGetCommand(opts Options) *cobra.Command {
370		var jsonOut bool
371		var format string
372		var branch string
373		cmd := &cobra.Command{
374			Use:   "multi-get <id>...",
375			Short: "Fetch multiple items by id",
376			Args:  cobra.MinimumNArgs(1),
377			RunE: func(cmd *cobra.Command, args []string) error {
378				wantJSON, err := outputWantsJSON(jsonOut, format)
379				if err != nil {
380					return err
381				}
382				return runGet(cmd.Context(), cmd, opts, args, branch, wantJSON, "multi-get")
383			},
384		}
385		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit machine-readable JSON")
386		cmd.Flags().StringVar(&format, "format", "", "Output format: json or cli (QMD-style alias for --json)")
387		cmd.Flags().StringVar(&branch, "branch", "", "Branch for facts (default: current)")
388		return cmd
389	}
390	
391	func outputWantsJSON(jsonOut bool, format string) (bool, error) {
392		switch strings.ToLower(strings.TrimSpace(format)) {
393		case "":
394			return jsonOut, nil
395		case "json":
396			return true, nil
397		case "cli":
398			return false, nil
399		default:
400			return false, fmt.Errorf("--format must be json or cli")
401		}
402	}
403	
404	func runGet(ctx context.Context, cmd *cobra.Command, opts Options, ids []string, branch string, jsonOut bool, surface string) error {
405		repoDir, brainDir, resolvedBranch, err := resolveFactsTarget(ctx, opts, agentSurfaceTarget(opts, nil), branch)
406		if err != nil {
407			return err
408		}
409		found, missing, err := getUnifiedBatch(repoDir, brainDir, resolvedBranch, ids)
410		if err != nil {
411			return err
412		}
413		factIDs := unifiedFactIDs(found)
414		recordReceipt := func() {
415			recordServedFacts(cmd.ErrOrStderr(), vitalityNow(opts), brainDir, resolvedBranch, surface,
416				vitalityHead(ctx, opts.Runner, repoDir), "", factIDs)
417		}
418		// Normalize empty collections to [] so --json emits arrays, not null, matching
419		// the repo's JSON contract (see TestInspectCodeEmptyResultsEmitArrayNotNull).
420		if found == nil {
421			found = []unifiedResult{}
422		}
423		if missing == nil {
424			missing = []string{}
425		}
426		if jsonOut {
427			if err := writeJSON(cmd, map[string]any{"branch": resolvedBranch, "results": found, "missing": missing}); err != nil {
428				return err
429			}
430			if len(factIDs) > 0 {
431				recordReceipt()
432			}
433			return nil
434		}
435		if err := writeText(cmd, func(out io.Writer) {
436			for _, r := range found {
437				loc := r.Path
438				if r.Line > 0 {
439					loc = fmt.Sprintf("%s:%d", r.Path, r.Line)
440				}
441				label := r.Source
442				if r.VerificationRequired {
443					label += " verify"
444				}
445				fmt.Fprintf(out, "[%s] %s  %s\n%s\n", label, r.ID, loc, r.Text)
446				printRetrievalCaveats(out, r)
447				fmt.Fprintln(out)
448			}
449			for _, id := range missing {
450				fmt.Fprintf(out, "not found: %s\n", id)
451			}
452		}); err != nil {
453			return err
454		}
455		if len(factIDs) > 0 {
456			recordReceipt()
457		}
458		return nil
459	}
460	
461	func printRetrievalCaveats(out io.Writer, result unifiedResult) {
462		for _, caveat := range result.Caveats {
463			fmt.Fprintf(out, "    verify: %s\n", caveat.Message)
464			details := make([]string, 0, 4)
465			if len(caveat.Paths) > 0 {
466				details = append(details, "paths="+strings.Join(caveat.Paths, ","))
467			}
468			if caveat.ReviewID != "" {
469				details = append(details, "review="+caveat.ReviewID)
470			}
471			if caveat.Action != "" {
472				details = append(details, "action="+caveat.Action)
473				details = append(details, fmt.Sprintf("confidence=%.2f", caveat.Confidence))
474			}
475			if len(details) > 0 {
476				fmt.Fprintf(out, "      details: %s\n", strings.Join(details, "  "))
477			}
478		}
479	}
