443	func handleMCPToolCall(ctx context.Context, opts Options, raw json.RawMessage) (map[string]any, error) {
444		if ctx == nil {
445			ctx = context.Background()
446		}
447		var params mcpToolCallParams
448		if err := json.Unmarshal(raw, &params); err != nil {
449			return nil, err
450		}
451		if err := validateMCPToolArguments(params.Name, params.Arguments); err != nil {
452			return nil, err
453		}
454		var out bytes.Buffer
455		cmd := &cobra.Command{Use: params.Name}
456		cmd.SetOut(&out)
457		cmd.SetErr(io.Discard)
458		cmd.SetContext(ctx)
459		defaultLimit := 20
460		switch params.Name {
461		case "brain_brief":
462			defaultLimit = brainBriefDefaultLimit
463		case "brain_tests":
464			defaultLimit = 3
465		case "brain_context":
466			defaultLimit = 5
467		case "brain_code", "brain_search_code":
468			defaultLimit = 10
469		}
470		limit, err := mcpPositiveInt(params.Arguments, "limit", defaultLimit)
471		if err != nil {
472			return nil, err
473		}
474		query, err := mcpOptionalString(params.Arguments, "query")
475		if err != nil {
476			return nil, err
477		}
478		branch, err := mcpOptionalString(params.Arguments, "branch")
479		if err != nil {
480			return nil, err
481		}
482		details, err := mcpBool(params.Arguments, "details")
483		if err != nil {
484			return nil, err
485		}
486		switch params.Name {
487		case "brain_status", "brain_index_status":
488			target := "."
489			if opts.Env.RepoRoot != "" {
490				target = opts.Env.RepoRoot
491			}
492			err = runAgentStatus(ctx, cmd, opts, agentStatusOptions{json: true, details: details, compact: true, failOn: semanticAuditFailOnNone}, target)
493		case "brain_refresh":
494			worktree := true
495			if _, provided := params.Arguments["worktree"]; provided {
496				worktree, err = mcpBool(params.Arguments, "worktree")
497				if err != nil {
498					break
499				}
500			}
501			force, boolErr := mcpBool(params.Arguments, "force")
502			if boolErr != nil {
503				err = boolErr
504				break
505			}
506			semantic, boolErr := mcpBool(params.Arguments, "semantic")
507			if boolErr != nil {
508				err = boolErr
509				break
510			}
511			refreshOpts := defaultRefreshCommandOptions()
512			refreshOpts.force = force
513			refreshOpts.seed.force = force
514			refreshOpts.graphBinary = mcpGraphBinary()
515			refreshOpts.skipSessions = true
516			refreshOpts.historyIndex = false
517			refreshOpts.semantic = semantic
518			refreshOpts.statusAfter = false
519			refreshOpts.seed.agent = "none"
520			refreshOpts.seed.worktree = worktree
521			refreshCmd := &cobra.Command{Use: "brain_refresh"}
522			refreshCmd.SetOut(io.Discard)
523			refreshCmd.SetErr(io.Discard)
524			refreshCtx, cancelRefresh := context.WithTimeout(ctx, mcpRefreshTimeout)
525			defer cancelRefresh()
526			refreshCmd.SetContext(refreshCtx)
527			err = runRefresh(refreshCtx, refreshCmd, opts, refreshOpts)
528			if errors.Is(refreshCtx.Err(), context.DeadlineExceeded) {
529				err = fmt.Errorf(
530					"brain_refresh exceeded the %s MCP limit; use the dedicated CLI refresh/index command",
531					mcpRefreshTimeout,
532				)
533			}
534			if err == nil {
535				target := "."
536				if opts.Env.RepoRoot != "" {
537					target = opts.Env.RepoRoot
538				}
539				err = runAgentStatus(ctx, cmd, opts, agentStatusOptions{json: true, compact: true, failOn: semanticAuditFailOnNone}, target)
540			}
541		case "brain_index_repository":
542			path, stringErr := mcpOptionalString(params.Arguments, "path")
543			if stringErr != nil {
544				err = stringErr
545				break
546			}
547			profile, profileErr := mcpOptionalString(params.Arguments, "profile")
548			if profileErr != nil {
549				err = profileErr
550				break
551			}
552			// The indexing binary is resolved from the trusted server environment,
553			// never from untrusted MCP client arguments: an arbitrary graph_binary would
554			// otherwise let a prompt-injected host (or a malicious client) run any
555			// executable. The path is normalized to the bound repo root and
556			// runSemanticIndex re-checks the *resolved* repo dir against containRoot so
557			// the client cannot point the indexer/subprocess outside the bound root.
558			graphBinary := mcpGraphBinary()
559			path, containRoot := mcpResolveIndexPath(opts.Env, path)
560			worktree, boolErr := mcpBool(params.Arguments, "worktree")
561			if boolErr != nil {
562				err = boolErr
563				break
564			}
565			force, boolErr := mcpBool(params.Arguments, "force")
566			if boolErr != nil {
567				err = boolErr
568				break
569			}
570			err = runSemanticIndex(ctx, cmd, opts, semanticIndexOptions{graphBinary: graphBinary, profile: strings.TrimSpace(profile), worktree: worktree, force: force, containRoot: containRoot}, path)
571		case "brain_list_projects":
572			err = runMCPListProjects(cmd, opts)
573		case "brain_delete_project":
574			repoKey, stringErr := mcpOptionalString(params.Arguments, "repo_key")
575			if stringErr != nil {
576				err = stringErr
577				break
578			}
579			err = runMCPDeleteProject(ctx, cmd, opts, strings.TrimSpace(repoKey))
580		case "brain_brief":
581			task, stringErr := mcpOptionalString(params.Arguments, "task")
582			if stringErr != nil {
583				err = stringErr
584				break
585			}
586			if strings.TrimSpace(task) == "" {
587				err = errors.New("task is required")
588			} else {
589				err = runBrainBrief(ctx, cmd, opts, brainBriefOptions{limit: limit, json: true, surface: "mcp:brain_brief"}, task)
590			}
591		case "brain_query":
592			err = requireMCPQuery(query)
593			if err == nil {
594				err = runRetrieve(ctx, cmd, opts, query, modeHybrid, limit, branch, true, false, "mcp:brain_query")
595			}
596		case "brain_search":
597			err = requireMCPQuery(query)
598			if err == nil {
599				err = runRetrieve(ctx, cmd, opts, query, modeLexical, limit, branch, true, false, "mcp:brain_search")
600			}
601		case "brain_vsearch":
602			err = requireMCPQuery(query)
603			if err == nil {
604				err = runRetrieve(ctx, cmd, opts, query, modeVector, limit, branch, true, false, "mcp:brain_vsearch")
605			}
606		case "brain_get":
607			id, stringErr := mcpOptionalString(params.Arguments, "id")
608			if stringErr != nil {
609				err = stringErr
610				break
611			}
612			id = strings.TrimSpace(id)
613			if id == "" {
614				err = errors.New("id is required")
615			} else {
616				err = runGet(ctx, cmd, opts, []string{id}, branch, true, "mcp:brain_get")
617			}
618		case "brain_multi_get":
619			ids, sliceErr := mcpStringSlice(params.Arguments, "ids")
620			if sliceErr != nil {
621				err = sliceErr
622				break
623			}
624			if len(ids) == 0 {
625				err = errors.New("ids is required")
626			} else {
627				err = runGet(ctx, cmd, opts, ids, branch, true, "mcp:brain_multi_get")
628			}
629		case "brain_context":
