958	// mcpResolveIndexPath normalizes an MCP-supplied repository path against the
959	// server's bound repository root (ENTIRE_REPO_ROOT) and returns the path to index
960	// plus the containment root to enforce. When a root is configured: an empty or
961	// "." path means the root itself, and a relative path resolves *inside* the root
962	// (never the process CWD). The returned containRoot is the root unless the
963	// operator opts out with ENTIRE_BRAIN_MCP_ALLOW_ANY_PATH (or no root is set);
964	// runSemanticIndex enforces it against the resolved git toplevel, which is the
965	// authoritative check — a path that resolves upward still cannot escape.
966	func mcpResolveIndexPath(env EntireEnv, path string) (resolved string, containRoot string) {
967		root := strings.TrimSpace(env.RepoRoot)
968		trimmed := strings.TrimSpace(path)
969		if root == "" {
970			if trimmed == "" {
971				return ".", ""
972			}
973			return trimmed, ""
974		}
975		if !envBool("ENTIRE_BRAIN_MCP_ALLOW_ANY_PATH") {
976			containRoot = root
977		}
978		switch {
979		case trimmed == "" || trimmed == ".":
980			return root, containRoot
981		case filepath.IsAbs(trimmed):
982			return trimmed, containRoot
983		default:
984			// Relative paths are resolved inside the bound root, not the CWD.
985			return filepath.Join(root, trimmed), containRoot
986		}
987	}
