989	// mcpToolAllowedArgs derives, per tool, the set of accepted argument names from
990	// the single source of truth — each tool's declared inputSchema in
991	// mcpToolDefinitions. This keeps argument validation from drifting away from the
992	// advertised tool schema.
993	func mcpToolAllowedArgs() map[string]map[string]bool {
994		defs := mcpToolDefinitions()
995		out := make(map[string]map[string]bool, len(defs))
996		for _, def := range defs {
997			name, _ := def["name"].(string)
998			if name == "" {
999				continue
1000			}
1001			allowed := map[string]bool{}
1002			if schema, ok := def["inputSchema"].(map[string]any); ok {
1003				if props, ok := schema["properties"].(map[string]any); ok {
1004					for key := range props {
1005						allowed[key] = true
1006					}
1007				}
1008			}
1009			out[name] = allowed
1010		}
1011		return out
1012	}
