1122	// errMCPRecoverable marks a single malformed/oversized frame that should be
1123	// answered with a JSON-RPC parse error rather than terminating the session.
1124	var errMCPRecoverable = errors.New("recoverable mcp frame error")
1125	
1126	// readBoundedLine reads one '\n'-terminated line while capping accumulated bytes
1127	// at max, so a newline-less giant frame cannot exhaust memory during the read
1128	// (ReadString would buffer it unbounded). On overflow it drains the remainder of
1129	// the line (bounded) to keep the stream aligned and returns errMCPRecoverable.
1130	func readBoundedLine(reader *bufio.Reader, max int) (string, error) {
1131		var buf []byte
1132		for {
1133			chunk, err := reader.ReadSlice('\n')
1134			if len(buf)+len(chunk) > max {
1135				if err == bufio.ErrBufferFull {
1136					drainMCPLine(reader)
1137				}
1138				return "", fmt.Errorf("%w: frame exceeds maximum size of %d bytes", errMCPRecoverable, max)
1139			}
1140			buf = append(buf, chunk...)
1141			switch err {
1142			case nil:
1143				return string(buf), nil
1144			case bufio.ErrBufferFull:
1145				continue
1146			default:
1147				return string(buf), err
1148			}
1149		}
1150	}
1151	
1152	// drainMCPLine discards the rest of an over-long line up to a bounded number of
1153	// buffer-sized chunks, then gives up (a pathological newline-less stream stays
1154	// memory-safe; only stream realignment is best-effort).
1155	func drainMCPLine(reader *bufio.Reader) {
1156		for i := 0; i < 64; i++ {
1157			if _, err := reader.ReadSlice('\n'); err != bufio.ErrBufferFull {
1158				return
1159			}
1160		}
1161	}
1162	
1163	func readMCPMessage(reader *bufio.Reader) (mcpMessage, mcpFrameMode, error) {
1164		length := -1
1165		for {
1166			line, err := readBoundedLine(reader, maxMCPFrameBytes)
1167			if errors.Is(err, errMCPRecoverable) {
1168				return mcpMessage{}, mcpFrameJSONLine, err
1169			}
1170			if err != nil {
1171				return mcpMessage{}, "", err
1172			}
1173			line = strings.TrimRight(line, "\r\n")
1174			if strings.HasPrefix(strings.TrimSpace(line), "{") {
1175				trimmed := strings.TrimSpace(line)
1176				// readBoundedLine already caps the line at maxMCPFrameBytes (an oversize
1177				// NDJSON frame is reported there), so the only failure left here is a
1178				// malformed line, which we make recoverable instead of fatal.
1179				var msg mcpMessage
1180				if err := json.Unmarshal([]byte(trimmed), &msg); err != nil {
1181					return mcpMessage{}, mcpFrameJSONLine, fmt.Errorf("%w: %v", errMCPRecoverable, err)
1182				}
1183				return msg, mcpFrameJSONLine, nil
1184			}
1185			if line == "" {
1186				break
1187			}
1188			name, value, ok := strings.Cut(line, ":")
1189			if ok && strings.EqualFold(strings.TrimSpace(name), "Content-Length") {
1190				parsed, err := strconv.Atoi(strings.TrimSpace(value))
1191				if err != nil {
1192					return mcpMessage{}, "", err
1193				}
1194				if parsed < 0 {
1195					return mcpMessage{}, "", errors.New("Content-Length must be non-negative")
1196				}
1197				length = parsed
1198			}
1199		}
1200		if length < 0 {
1201			return mcpMessage{}, "", errors.New("missing Content-Length")
1202		}
1203		if length > maxMCPFrameBytes {
1204			return mcpMessage{}, "", fmt.Errorf("Content-Length exceeds maximum frame size of %d bytes", maxMCPFrameBytes)
1205		}
1206		data := make([]byte, length)
1207		if _, err := io.ReadFull(reader, data); err != nil {
1208			return mcpMessage{}, "", err
1209		}
1210		var msg mcpMessage
1211		if err := json.Unmarshal(data, &msg); err != nil {
1212			return mcpMessage{}, "", err
1213		}
1214		return msg, mcpFrameContentLength, nil
1215	}
1216	
1217	func writeMCPMessage(out io.Writer, msg mcpMessage, frameMode mcpFrameMode) error {
1218		data, err := json.Marshal(msg)
1219		if err != nil {
1220			return err
1221		}
1222		if frameMode == mcpFrameJSONLine {
