11	const (
12		retrievalCaveatStaleLocus               = "stale_locus"
13		retrievalCaveatUnresolvedReview         = "unresolved_fact_proposal"
14		retrievalCaveatProposalStateUnavailable = "proposal_state_unavailable"
15		retrievalCaveatCurrentCodeUnavailable   = "current_code_unavailable"
16		retrievalCaveatHistoricalDocument       = "historical_document"
17	)
18	
19	// retrievalCaveat is a machine-readable reason an agent must verify a memory
20	// result against current evidence before relying on it.
21	type retrievalCaveat struct {
22		Kind       string   `json:"kind"`
23		Message    string   `json:"message"`
24		Paths      []string `json:"paths,omitempty"`
25		ReviewID   string   `json:"review_id,omitempty"`
26		Action     string   `json:"action,omitempty"`
27		Confidence float64  `json:"confidence,omitempty"`
28	}
29	
30	type factReviewGroup struct {
31		ID        string
32		Facts     []factRecord
33		Proposals []factProposal
34	}
35	
36	// buildFactReviewGroups turns the pending proposal graph into stable connected
37	// components. Only valid proposals between two active facts affect retrieval;
38	// stale queue entries remain available to the review command but cannot hide or
39	// relabel an otherwise independent fact.
40	func buildFactReviewGroups(facts []factRecord, proposals []factProposal) []factReviewGroup {
41		active := make(map[string]factRecord, len(facts))
42		for _, fact := range facts {
43			if fact.Status == factStatusActive {
44				active[fact.ID] = fact
45			}
46		}
47	
48		parent := make(map[string]string)
49		var findRoot func(string) string
50		findRoot = func(id string) string {
51			p, ok := parent[id]
52			if !ok {
53				parent[id] = id
54				return id
55			}
56			if p != id {
57				parent[id] = findRoot(p)
58			}
59			return parent[id]
60		}
61		union := func(a, b string) {
