13	//
14	//   - The arm is gated on a fusion-eligible embedder (the historyFusionEligible
15	//     marker, implemented by the external ollama/EmbeddingGemma embedder and
16	//     never by Model2Vec).
17	//   - Record vectors are embedded at refresh time into a persistent vec0 store
18	//     (syncHistoryVectors), never lazily at query time: a large repo holds
19	//     hundreds of thousands of records, hours of embedding that must not land
20	//     on a query. Records newer than the last refresh simply have no vector
21	//     until the next one — the lexical arm still sees them.
22	//   - The store is brain_cgo-only (newHistoryVectorStore returns ok=false on
23	//     the pure-Go build): at this row count the vectors.bin flat file +
24	//     brute-force scan would be loaded whole on every query, so without vec0
25	//     the gate stays closed and history stays BM25-only.
26	
27	// historyVectorStore is the persistent store for history record vectors.
28	// Unlike the facts vectorStore (a full-rewrite cache sized for hundreds of
29	// rows) it must scale to hundreds of thousands, so its writes are incremental:
30	// upsert new ids, drop departed ones, never rewrite the present set.
31	type historyVectorStore interface {
32		// ids returns the stored record-id set; ok=false means the store is absent
33		// or was built for another model/dim (callers treat both as empty: every
34		// wanted vector is missing and a sync rebuilds from scratch).
35		ids() (map[string]struct{}, bool)
36		upsert(add map[string][]float32, drop []string) error
37		// knnCos returns cosine similarity for the k nearest records only — unlike
38		// the facts store's all-rows variant. vec0 caps MATCH k (and a history KNN
39		// over hundreds of thousands of rows shouldn't materialize them all anyway);
40		// callers over-fetch enough for downstream dedup, nothing more.
41		knnCos(qvec []float32, k int) (map[string]float64, bool)
42	}
43	
44	// historyFusionEligible marks embedders validated for history fusion. The
45	// capstone measured Model2Vec fusion significantly below BM25 on history
46	// precision at scale, so eligibility is opt-in per embedder type — a new
47	// embedder joins the history semantic arm by implementing this marker after
48	// it has an eval-ledger row, not by existing.
49	type historyFusionEligible interface {
50		historyFusionEligible() bool
51	}
52	
53	// historySemanticEmbedder filters e down to the history-fusion gate: it
54	// returns e only when e is fusion-eligible, nil otherwise (including nil e).
55	func historySemanticEmbedder(e Embedder) Embedder {
56		if fe, ok := e.(historyFusionEligible); ok && fe.historyFusionEligible() {
57			return e
58		}
59		return nil
60	}
61	
62	// historyVectorStoreFor resolves the persistent store for a gate-filtered
63	// embedder. A nil e (gate closed) reports no store without consulting the
64	// build, so callers can branch on "why" — gate vs build — for messaging.
65	func historyVectorStoreFor(brainDir string, e Embedder) (historyVectorStore, bool) {
66		if e == nil {
67			return nil, false
68		}
69		return newHistoryVectorStore(brainDir, e.ID(), e.Dim())
70	}
71	
72	// historySemanticScores embeds the query and runs one KNN over the persisted
73	// history vectors. Automatic retrieval requests a fixed, bounded calibration
74	// neighborhood rather than tying its score distribution to the display limit:
75	// calibrating only the nearest limit*4 rows becomes increasingly flat as a
76	// history corpus grows and can suppress a real upper tail. Explicit vector
77	// search does not calibrate and retains its smaller limit*4 budget. The vec0
78	// store clamps either request to its row count and backend ceiling; downstream
79	// rankers apply the user-facing limit.
80	// nil means the semantic arm is unavailable for this query (gate closed
81	// upstream, no store, model/dim mismatch, embedder down) — every caller falls
82	// back to lexical-only, so a degraded arm never breaks ranking.
83	func historySemanticScores(brainDir string, e Embedder, query string, limit int, calibrate bool) map[string]float64 {
84		if e == nil || limit <= 0 {
85			return nil
86		}
87		store, ok := newHistoryVectorStore(brainDir, e.ID(), e.Dim())
88		if !ok {
89			return nil
90		}
91		return historySemanticScoresWithStore(store, e, query, limit, calibrate)
92	}
93	
94	func historySemanticScoresWithStore(store historyVectorStore, e Embedder, query string, limit int, calibrate bool) map[string]float64 {
95		if store == nil || e == nil || limit <= 0 {
96			return nil
97		}
98		qvec := embedQueryWith(e, query)
99		if e.Dim() <= 0 || len(qvec) != e.Dim() || !vectorHasMagnitude(qvec) {
100			return nil
101		}
102		scoreBudget := limit * 4
103		if scoreBudget < limit { // integer overflow guard for unreasonable inputs
104			scoreBudget = limit
105		}
106		if calibrate && scoreBudget < historySemanticCalibrationK {
107			scoreBudget = historySemanticCalibrationK
108		}
109		scores, ok := store.knnCos(qvec, scoreBudget)
110		if !ok {
111			return nil
112		}
113		return scores
114	}
115	
116	// rankHistorySemantic orders the index's rankable records by the cosine scores
117	// of one historySemanticScores call. Request records are excluded and duplicate
118	// summaries collapsed, exactly like the lexical scorers, so the semantic arm
119	// can never resurface what they deliberately hide. Records without a stored
120	// vector (added since the last refresh) are skipped, not zero-scored.
121	func rankHistorySemantic(index historyIndex, scores map[string]float64, limit int) []scoredHistoryRecord {
122		return rankHistorySemanticFiltered(index, scores, limit, false, nil, false).ranked
123	}
124	
125	// rankHistorySemanticRelevant is the automatic history arm. Unlike explicit
126	// vector search, it admits only a corpus-relative upper cluster.
127	func rankHistorySemanticRelevant(index historyIndex, scores map[string]float64, limit int) []scoredHistoryRecord {
128		return rankHistorySemanticFiltered(index, scores, limit, true, nil, false).ranked
129	}
130	
131	// rankHistorySemanticHybrid keeps every lexical hit in the semantic ranking so
132	// cosine can still reorder evidence already reached by lexical search. Only
133	// semantic-only candidates must clear corpus-relative calibration.
134	func rankHistorySemanticHybrid(index historyIndex, scores map[string]float64, limit int, lexicalIDs map[string]struct{}) []scoredHistoryRecord {
135		return rankHistorySemanticHybridRanks(index, scores, limit, lexicalIDs).ranked
136	}
137	
138	type historyVectorRanks struct {
139		ranked                 []scoredHistoryRecord
140		calibratedSemanticOnly []scoredHistoryRecord
141	}
142	
143	// rankHistorySemanticHybridRanks gives a high-confidence semantic-only record
144	// the same two-list RRF opportunity as a record reached by both lexical and
145	// semantic search. The calibration-only list excludes lexical hits, so no
146	// record can receive three votes. Its independent limit also prevents lexical
147	// hits at the top of ranked from crowding all term-disjoint evidence out.
148	func rankHistorySemanticHybridRanks(index historyIndex, scores map[string]float64, limit int, lexicalIDs map[string]struct{}) historyVectorRanks {
149		return rankHistorySemanticFiltered(index, scores, limit, true, lexicalIDs, true)
150	}
151	
152	func rankHistorySemanticFiltered(
153		index historyIndex,
154		scores map[string]float64,
155		limit int,
156		requireRelevance bool,
157		alwaysKeep map[string]struct{},
158		collectCalibrationArm bool,
159	) historyVectorRanks {
160		if len(scores) == 0 || limit <= 0 {
161			return historyVectorRanks{}
162		}
163		type cand struct {
164			rec     historyRecord
165			cos     float64
166			order   int
167			keep    bool
168			lexical bool
169		}
170		cands := make([]cand, 0, min(limit, len(scores)))
171		seen := map[string]struct{}{}
172		for i, r := range index.Records {
173			if r.Kind == "request" {
174				continue
175			}
176			cos, ok := scores[r.ID]
177			if !ok || !isFinite(cos) {
178				continue
179			}
180			key := normalizeHistorySearchText(r.Summary)
181			if _, dup := seen[key]; dup {
182				continue
183			}
184			seen[key] = struct{}{}
185			cands = append(cands, cand{rec: r, cos: cos, order: i})
186		}
187		if requireRelevance {
188			cosines := make([]float64, len(cands))
189			for i := range cands {
190				cosines[i] = cands[i].cos
191			}
192			mask := semanticResultMask(
193				cosines, true, semanticMedianBackgrounds(cosines),
194			)
195			for i := range cands {
196				_, lexical := alwaysKeep[cands[i].rec.ID]
197				cands[i].keep = mask[i]
198				cands[i].lexical = lexical
199			}
200		} else {
201			for i := range cands {
202				cands[i].keep = true
203			}
204		}
205		sort.SliceStable(cands, func(a, b int) bool {
206			if cands[a].cos != cands[b].cos {
207				return cands[a].cos > cands[b].cos
208			}
209			return cands[a].rec.ID < cands[b].rec.ID
210		})
211		out := historyVectorRanks{
212			ranked:                 make([]scoredHistoryRecord, 0, min(limit, len(cands))),
213			calibratedSemanticOnly: make([]scoredHistoryRecord, 0),
214		}
215		for _, c := range cands {
216			// Same float→int display scaling as rankHistoryViaFTS; the list is
217			// already ordered, Score is informational.
218			record := scoredHistoryRecord{Record: c.rec, Score: int(c.cos*1000 + 0.5), Order: c.order}
219			if (c.keep || c.lexical) && len(out.ranked) < limit {
220				out.ranked = append(out.ranked, record)
221			}
222			if collectCalibrationArm && c.keep && !c.lexical && len(out.calibratedSemanticOnly) < limit {
223				out.calibratedSemanticOnly = append(out.calibratedSemanticOnly, record)
224			}
225			if len(out.ranked) >= limit && (!collectCalibrationArm || len(out.calibratedSemanticOnly) >= limit) {
226				break
227			}
228		}
229		return out
230	}
231	
232	// rankHistoryFused is rankHistoryViaFTS with validated semantic rankings fused
233	// in via RRF: lexical ranks over-fetched 4×, semantic ranks over the full
234	// stored candidate set, and a calibration-only list that restores two-list
235	// parity for term-disjoint evidence without triple-counting lexical hits. All
236	// lists use k=60 and equal weight. When
237	// the gate is closed or the store is unavailable it degrades to exactly
238	// rankHistoryViaFTS — same list, same ok contract — so call sites need no
239	// fallback of their own beyond what they already have.
240	func rankHistoryFused(brainDir string, index historyIndex, kind, query string, limit int, e Embedder) ([]scoredHistoryRecord, bool) {
241		scores := historySemanticScores(brainDir, historySemanticEmbedder(e), query, limit, true)
242		if len(scores) == 0 {
243			return rankHistoryViaFTS(brainDir, index, kind, query, limit)
244		}
245		lex, lexOK := rankHistoryViaFTS(brainDir, index, kind, query, limit*4)
246		if !lexOK {
247			// FTS down but vectors up: rank on the semantic arm alone rather than
248			// reporting the whole indexed path unavailable (which would drop the
249			// caller to the substring scorer the eval retired).
250			sem := rankHistorySemanticRelevant(index, scores, limit)
251			return sem, len(sem) > 0
252		}
253		lexicalIDs := make(map[string]struct{}, len(lex))
254		for _, scored := range lex {
255			lexicalIDs[scored.Record.ID] = struct{}{}
256		}
257		sem := rankHistorySemanticHybridRanks(index, scores, limit*4, lexicalIDs)
258		type fusedRec struct {
259			s     scoredHistoryRecord
260			score float64
261		}
262		fused := map[string]*fusedRec{}
263		for _, list := range [][]scoredHistoryRecord{lex, sem.ranked, sem.calibratedSemanticOnly} {
264			for rank, s := range list {
265				f, ok := fused[s.Record.ID]
266				if !ok {
267					f = &fusedRec{s: s}
268					fused[s.Record.ID] = f
269				}
270				f.score += 1.0 / (rrfK + float64(rank+1))
271			}
272		}
273		out := make([]*fusedRec, 0, len(fused))
274		for _, f := range fused {
275			out = append(out, f)
276		}
277		sort.SliceStable(out, func(a, b int) bool {
278			if out[a].score != out[b].score {
279				return out[a].score > out[b].score
280			}
281			return out[a].s.Record.ID < out[b].s.Record.ID
282		})
283		if len(out) > limit {
284			out = out[:limit]
285		}
286		result := make([]scoredHistoryRecord, len(out))
287		for i, f := range out {
288			// Same float→int display scaling as rankHistoryViaFTS (RRF scores are
289			// small; ordering is carried by list position, Score is informational).
290			result[i] = scoredHistoryRecord{Record: f.s.Record, Score: int(f.score*1000 + 0.5), Order: f.s.Order}
291		}
292		return result, true
293	}
294	
295	// syncHistoryVectors brings the persisted store in line with the index:
296	// embed records that are rankable but unstored, drop stored ids the index no
297	// longer contains. Writes are batched so an interrupted backfill (the first
298	// sync of a large repo embeds every record and can run for hours) resumes
299	// where it stopped instead of starting over. Identical summaries are embedded
300	// once per sync and the vector shared across their record ids — templated
301	// session lines repeat heavily, and the store is keyed by record id so KNN
302	// results map straight back to records.
303	func syncHistoryVectors(store historyVectorStore, index historyIndex, e Embedder, progress func(done, total int)) (added, dropped, total int, err error) {
304		existing, _ := store.ids() // !ok reads as empty: a fresh or mismatched store rebuilds
305		want := map[string]struct{}{}
306		for _, r := range index.Records {
307			if r.Kind == "request" {
308				continue
309			}
310			want[r.ID] = struct{}{}
311		}
312		var drop []string
313		for id := range existing {
314			if _, ok := want[id]; !ok {
315				drop = append(drop, id)
316			}
317		}
318		var missing []historyRecord
319		for _, r := range index.Records {
320			if r.Kind == "request" {
321				continue
322			}
323			if _, ok := existing[r.ID]; !ok {
324				missing = append(missing, r)
325			}
326		}
327		if len(drop) > 0 {
328			if err := store.upsert(nil, drop); err != nil {
329				return 0, 0, 0, err
330			}
331		}
332		const flushEvery = 1024
333		bySummary := map[string][]float32{}
334		batch := map[string][]float32{}
335		for i, r := range missing {
336			v, ok := bySummary[r.Summary]
337			if !ok {
338				v = e.Embed(r.Summary)
339				if len(v) != e.Dim() {
340					// Embedder fault mid-sync (server died, transient error). Flush
341					// what we have so the next sync resumes here, then surface it.
342					if ferr := store.upsert(batch, nil); ferr != nil {
343						return added, len(drop), len(want), ferr
344					}
345					return added + len(batch), len(drop), len(want), fmt.Errorf("embedder returned no vector for record %s (embed server down mid-sync?); progress saved, re-run refresh to resume", r.ID)
346				}
347				bySummary[r.Summary] = v
348			}
349			batch[r.ID] = v
350			if len(batch) >= flushEvery {
351				if err := store.upsert(batch, nil); err != nil {
352					return added, len(drop), len(want), err
353				}
354				added += len(batch)
355				batch = map[string][]float32{}
356				if progress != nil {
357					progress(i+1, len(missing))
358				}
359			}
360		}
361		if len(batch) > 0 {
362			if err := store.upsert(batch, nil); err != nil {
363				return added, len(drop), len(want), err
364			}
365			added += len(batch)
366		}
367		if progress != nil && len(missing) > 0 {
368			progress(len(missing), len(missing))
369		}
370		return added, len(drop), len(want), nil
371	}
