// recentDecisionMatches returns the most recent decision records so an agent can
// see how the project's design has been steered, newest first.
func recentDecisionMatches(brainDir string, source *historySourceManifest, limit int) []brainTextMatch {
	if limit <= 0 {
		return nil
	}
	index, err := loadBrainHistoryIndex(brainDir, source)
	if err != nil {
		return nil
	}
	var decisions []historyRecord
	for _, record := range index.Records {
		if record.Kind == "decision" {
			decisions = append(decisions, record)
		}
	}
	sort.SliceStable(decisions, func(i, j int) bool {
		left, leftOK := historyRecordTimestamp(decisions[i].Path)
		right, rightOK := historyRecordTimestamp(decisions[j].Path)
		if leftOK && rightOK && !left.Equal(right) {
		if arm == nil {
			arm = flatArm
		}
		return factsToEvalItems(arm(facts, query, limit, rr)), nil
	case evalRetrieverHistory:
		manifest, err := loadBrainManifest(brainDir)
		if err != nil {
			return nil, err
		}
		if manifest.Sources == nil || manifest.Sources.History == nil {
			return nil, nil
		}
		index, err := loadBrainHistoryIndex(brainDir, manifest.Sources.History)
		if err != nil {
			return nil, err
		}
		index = filterHistoryIndexForEvalBranch(index, branch, manifest)
		return historyScoredToEvalItems(rankHistoryRecordsScored(index, "history", query, limit, 0)), nil
	case evalRetrieverQuery:
		results, err := retrieveEvalUnifiedLexical(brainDir, branch, query, limit, facts)
		if err != nil {
			return nil, err
		}
		return unifiedToEvalItems(results), nil
	case evalRetrieverRawSessions:
		return rankRawSessionChunks(brainDir, branch, query, limit)
	default:
		return nil, fmt.Errorf("unsupported retriever %q", retriever)
	}
}

