		ID:                   record.ID,
		Path:                 record.Path,
		Heading:              conversationKind,
		Line:                 record.Line,
		EndLine:              record.EndLine,
		Branch:               record.Branch,
		SessionID:            record.SessionID,
		Agent:                record.Agent,
		CreatedAt:            record.CreatedAt,
		Text:                 record.Summary,
		Truncated:            record.ProjectionTruncated,
		VerificationRequired: true,
